begin;

do $do$
declare
  v_id uuid;
  v_lecons jsonb;
  v_module0 jsonb := $wb$[{"titre":"Leçon 0.1 — Le principe, le marché BRVM et les sources","module":"Module 0 — Le cours complet : analyse fondamentale appliquée à la BRVM","categorie":"fundamental","duree_min":14,"sous_titre":"Analyser l’entreprise avant son action : quatre questions, un parcours en six étapes, les particularités de la BRVM et les sources à privilégier.","resume":"L’analyse fondamentale estime la valeur économique d’une entreprise à partir de ses comptes, de son activité, de ses perspectives et des risques qu’elle encourt, puis compare cette valeur estimée au cours de bourse. Cette leçon ouvre le cours complet : les quatre questions à se poser, le parcours d’analyse en six étapes, ce qui distingue la BRVM d’une grande place financière, et les sources à consulter, dans l’ordre de fiabilité.","nouveaute":{"type":"nouveau","depuis":"2026-11-24"},"sections":[{"type":"definition","titre":"Le principe : analyser l’entreprise avant son action","contenu":"L’analyse fondamentale consiste à estimer la valeur économique d’une entreprise à partir de ses comptes, de son activité, de ses perspectives et des risques qu’elle encourt. L’objectif est de comparer cette valeur estimée avec le cours en bourse, puis de juger si l’écart justifie un investissement.\nElle s’oppose à une lecture qui ne regarde que le graphique du cours. Un cours monte ou baisse pour des raisons très diverses ; l’analyse fondamentale cherche ce que l’entreprise produit réellement, en bénéfices et en trésorerie, et ce que l’acheteur paie pour y avoir droit.\nQuatre questions structurent tout le travail. Chacune renvoie à des documents et à des ratios précis, que les leçons suivantes détaillent un par un, puis appliquent à quatre sociétés cotées : deux banques, Ecobank Côte d’Ivoire et Société Générale Côte d’Ivoire, et deux opérateurs de télécommunications, Sonatel et Orange Côte d’Ivoire.","points":[{"titre":"L’entreprise est-elle solide ?","detail":"Qualité des actifs, niveau d’endettement, liquidité, réserves, risques identifiés dans le rapport d’audit.","verifier":"Le rapport des commissaires aux comptes : opinion sans réserve ?"},{"titre":"Est-elle rentable ?","detail":"Croissance du chiffre d’affaires ou du produit net bancaire (PNB), évolution des marges, rendement des capitaux propres (ROE), rendement des actifs (ROA).","verifier":"Les marges sur au moins trois exercices, pas sur un seul."},{"titre":"Génère-t-elle de la trésorerie ?","detail":"Le bénéfice comptable n’est pas la trésorerie. Il faut examiner les flux de trésorerie opérationnels et disponibles (free cash flow).","verifier":"Le tableau des flux : les flux d’exploitation suivent-ils le résultat ?"},{"titre":"Le cours est-il raisonnable ?","detail":"Le PER, le P/B et le rendement du dividende permettent de comparer le prix payé avec les résultats générés, en tenant compte de la liquidité du titre.","verifier":"Le volume échangé : le cours affiché est-il un prix réellement praticable ?"}],"etapes":[{"titre":"Comprendre l’activité et le modèle économique","detail":"Ce que l’entreprise vend, à qui, avec quels coûts et face à quels concurrents."},{"titre":"Vérifier les comptes et leur qualité","detail":"Rapport d’audit, annexes, changements de méthode, opérations exceptionnelles."},{"titre":"Mesurer croissance, rentabilité et risques sur plusieurs années","detail":"Au moins trois exercices, avec les mêmes définitions d’une année sur l’autre."},{"titre":"Estimer la valeur de l’action","detail":"Multiples (PER, P/B), actualisation des flux (DCF), dividende.","cle":true},{"titre":"Tenir compte du cours, de la liquidité et du prix d’exécution","detail":"Volumes, flottant, écart entre le prix demandé et le prix offert."},{"titre":"Conclure avec des hypothèses et des risques explicites","detail":"Une valorisation est une approximation : ses hypothèses doivent être écrites.","cle":true}],"etapes_style":"frise","encadres":[{"ton":"cle","titre":"Règle d’or","texte":"Un PER faible ne suffit pas à prouver qu’une action est bon marché. Le bénéfice peut être exceptionnel, le risque élevé, la liquidité insuffisante ou les perspectives dégradées. Toujours croiser plusieurs indicateurs."}]},{"type":"importance","titre":"La BRVM : ce qui change la lecture des chiffres","contenu":"La Bourse Régionale des Valeurs Mobilières (BRVM) regroupe les sociétés de l’UEMOA, soit huit pays : Côte d’Ivoire, Sénégal, Burkina Faso, Mali, Niger, Bénin, Togo et Guinée-Bissau. Son marché présente des particularités qui influencent directement l’analyse fondamentale.\nLa liquidité en donne la mesure. Lors de la séance du 23 novembre 2026, 88 961 actions Sonatel ont changé de mains, contre 2 509 actions Orange Côte d’Ivoire. Les deux sociétés pèsent pourtant plusieurs milliers de milliards de FCFA en bourse : sur la seconde, un ordre important peut à lui seul déplacer le cours.\nLe tableau ci-dessous reprend les six particularités à garder en tête, leur effet sur l’analyse et la précaution qui va avec. Le bloc suivant affiche les derniers cours de quatre grandes valeurs, lus en base au moment où vous ouvrez la leçon.","stats":[{"label":"Titres Sonatel échangés le 23/11/2026","valeur":"88 961","detail":"Séance de la BRVM, base WESTBOURSE"},{"label":"Titres Orange CI échangés le même jour","valeur":"2 509","detail":"Soit 35 fois moins"}],"tableau":{"colonnes":["Caractéristique","Impact sur l’analyse","Précaution"],"lignes":[["Liquidité parfois limitée","Certaines actions s’échangent peu. Le dernier cours affiché peut ne pas représenter un prix auquel on peut acheter ou vendre une quantité importante.","Vérifier les volumes quotidiens et l’écart achat-vente (bid-ask spread)."],["Flottant variable","Une grande partie du capital est souvent détenue par des actionnaires de référence, ce qui réduit les titres réellement disponibles.","Consulter le nombre d’actions en circulation et le pourcentage de flottant."],["Écarts achat-vente importants","Le prix demandé par les vendeurs peut être très éloigné du prix offert par les acheteurs.","Ne pas se fier au seul cours de clôture. Examiner le carnet d’ordres."],["Données à dates variables","Les rapports peuvent être publiés à des dates différentes selon les sociétés.","Homogénéiser les périodes comparées. Toujours indiquer la date de chaque donnée."],["Diversité sectorielle","Banque, assurance, télécoms, agro-industrie, distribution, énergie : les ratios pertinents ne sont pas les mêmes.","Ne pas comparer mécaniquement les postes d’une banque avec ceux d’une entreprise industrielle."],["Référentiel SYSCOHADA","Les états financiers sont préparés selon le SYSCOHADA révisé, avec des règles propres aux banques et aux assurances.","Vérifier si des comptes consolidés en normes IFRS sont aussi publiés."]],"note":"Le carnet d’ordres de chaque valeur figure sur sa fiche société : la BRVM publie chaque séance la meilleure limite de chaque côté dans son Bulletin officiel de la cote."},"donnees_reelles":{"vue":"cours","codes":["SNTS","ORAC","ECOC","SGBC"],"actions":10}},{"type":"definition","titre":"Les sources à privilégier, dans l’ordre","contenu":"Une analyse ne vaut que par ses données. Les sources n’ont pas toutes le même statut : les documents publiés par la société et par la bourse font foi ; les sites d’information et les bases de données retraitent ces documents, parfois avec des définitions différentes.\nCe cours le montre sur des cas réels. Pour une même banque, deux séries de produit net bancaire circulent selon qu’on lit les comptes publiés ou une base standardisée ; pour un même opérateur, trois PER coexistent selon le bénéfice retenu. Aucune n’est fausse : elles ne mesurent pas la même chose.","etapes":[{"titre":"BRVM (brvm.org)","detail":"Rapports d’activité, états financiers, avis et communiqués, cours quotidiens et Bulletin officiel de la cote. Source primaire pour les données officielles.","cle":true},{"titre":"Le site de la société cotée","detail":"Rapport annuel complet, présentation aux investisseurs, communiqués de presse, documents d’assemblée générale."},{"titre":"Sika Finance (sikafinance.com)","detail":"Cotations en différé, historiques, fiches sociétés, dividendes, actualités et analyses."},{"titre":"Richbourse (richbourse.com)","detail":"Outils de suivi, historiques, fiches de sociétés et informations de marché BRVM."},{"titre":"StockAnalysis / S&P Global Market Intelligence","detail":"États financiers standardisés sur cinq ans et plus, ratios calculés : utile pour comparer plusieurs années, à condition de connaître ses définitions."},{"titre":"FGI Bourse, CGF Bourse, allAfrica, Daba Finance","detail":"Analyses sectorielles, commentaires de résultats trimestriels, contexte macroéconomique régional."}],"encadres":[{"ton":"info","titre":"Règle éditoriale","texte":"Distinguez toujours les données publiées par la société (rapports, communiqués), les cours de marché (BRVM, Sika Finance) et vos propres calculs. Indiquez la période comptable, la date du cours retenu, la devise, les unités et la définition du ratio utilisé."}]},{"type":"retenir","titre":"L’essentiel","contenu":"L’analyse fondamentale compare une valeur estimée à un prix. Elle se construit sur plusieurs exercices, avec des définitions stables, et elle tient compte de ce qui fait la BRVM : une liquidité inégale, un flottant souvent réduit et des comptes publiés à des dates différentes.","points":[{"titre":"Quatre questions","detail":"Solidité, rentabilité, trésorerie, prix : aucune ne suffit seule."},{"titre":"Six étapes","detail":"De la compréhension de l’activité à une conclusion qui écrit ses hypothèses."},{"titre":"Une source datée pour chaque chiffre","detail":"Les comptes et la cote font foi ; les bases de données les retraitent."}]}],"quiz":[{"question":"Quel est l’objectif de l’analyse fondamentale ?","options":["Prévoir le cours de la prochaine séance à partir du graphique","Comparer une valeur estimée de l’entreprise à son cours","Suivre les volumes échangés chaque jour sur la cote","Classer les sociétés cotées selon leur taille"],"correct":1,"explication":"Elle estime la valeur économique de l’entreprise à partir de ses comptes, de son activité et de ses risques, puis la compare au cours."},{"question":"Le 23 novembre 2026, une société a vu s’échanger 2 509 de ses actions. Quelle précaution s’impose avant de se fier à son dernier cours ?","options":["Aucune, le dernier cours est toujours exécutable","Regarder le volume et le carnet d’ordres","Ne regarder que le PER","Attendre la publication du rapport annuel"],"correct":1,"explication":"Sur un titre peu échangé, le dernier cours peut ne pas être un prix praticable pour une quantité importante : volume et carnet d’ordres le disent."},{"question":"Pourquoi un PER faible ne suffit-il pas à conclure qu’une action est bon marché ?","options":["Parce que le PER ne dépend pas du cours de bourse","Parce que le bénéfice peut être exceptionnel ou le risque élevé","Parce que le PER n’existe que sur les bourses européennes et américaines","Parce qu’un PER faible est toujours une erreur de calcul"],"correct":1,"explication":"Un bénéfice non récurrent, un risque élevé, une liquidité insuffisante ou des perspectives dégradées peuvent expliquer un PER bas : c’est la règle d’or de la leçon."},{"question":"Quelle source fait foi pour les états financiers d’une société cotée à la BRVM ?","options":["Un forum de discussion entre investisseurs de la région","Une base de données standardisée","Les documents publiés par la société et par la BRVM","Le dernier article de presse publié sur la société"],"correct":2,"explication":"Les rapports et états financiers publiés par la société et diffusés par la BRVM sont la source primaire ; les bases de données les retraitent."},{"question":"Selon quel référentiel les sociétés cotées à la BRVM préparent-elles leurs comptes ?","options":["Le SYSCOHADA révisé, avec des plans propres aux banques","Les normes comptables américaines, communes à toutes les places financières","Aucun référentiel commun","Le plan comptable français de 1982"],"correct":0,"explication":"Le SYSCOHADA révisé s’applique ; banques et assurances suivent des plans spécifiques, et certains groupes publient aussi des comptes consolidés en IFRS."}],"qcm":{"question":"Quel est l’objectif de l’analyse fondamentale ?","options":["Prévoir le cours de la prochaine séance à partir du graphique","Comparer une valeur estimée de l’entreprise à son cours","Suivre les volumes échangés chaque jour sur la cote","Classer les sociétés cotées selon leur taille"],"correct":1,"explication":"Elle estime la valeur économique de l’entreprise à partir de ses comptes, de son activité et de ses risques, puis la compare au cours."},"liens":[{"label":"Toutes les actions de la BRVM","href":"/actions"},{"label":"La liquidité de chaque valeur","href":"/liquidite"},{"label":"Les fiches sociétés","href":"/societes"}],"avertissement":"Ceci n’est pas un conseil en investissement. Les ratios décrivent le passé et ne garantissent aucune performance future. Investir en actions comporte un risque de perte en capital."},{"titre":"Leçon 0.2 — Les ratios essentiels : formules et calculateurs","module":"Module 0 — Le cours complet : analyse fondamentale appliquée à la BRVM","categorie":"fundamental","duree_min":18,"sous_titre":"Croissance, rentabilité, valorisation, endettement : chaque formule, un exemple tiré des comptes réels et un calculateur pour s’exercer.","resume":"Quatre familles de ratios suffisent pour l’essentiel de l’analyse : la croissance (d’une année sur l’autre et en moyenne annuelle), la rentabilité (marge, ROE, ROA), la valorisation boursière (BPA, PER, P/B, rendement du dividende) et, pour les entreprises non financières, l’endettement. Chaque formule est illustrée par un calcul posé sur des comptes publiés, et des calculateurs permettent de refaire les calculs avec vos propres chiffres.","nouveaute":{"type":"nouveau","depuis":"2026-11-24"},"sections":[{"type":"definition","titre":"Croissance : d’une année sur l’autre, et en moyenne annuelle","contenu":"La croissance se mesure d’abord d’une année sur l’autre. Sur plusieurs années, on calcule un taux de croissance annuel moyen (TCAM), qui lisse le parcours : il dit à quel rythme régulier il aurait fallu croître pour passer de la valeur de départ à la valeur d’arrivée.\nExemple réel : le produit net bancaire d’Ecobank Côte d’Ivoire est passé de 90,5 à 132,7 milliards de FCFA entre 2021 et 2025, soit +46,6 % en quatre ans et un TCAM de 10,0 %. En 2025 seule, la progression est de 8,5 %.\nLe nombre d’années n est l’écart entre les deux exercices : de 2021 à 2025, il y en a quatre, pas cinq. C’est l’erreur la plus fréquente sur ce calcul.","formules":[{"nom":"Croissance annuelle (chiffre d’affaires ou PNB)","expression":"Croissance = (CA de l’année N ÷ CA de l’année N−1 − 1) × 100","exemple":"132,7 ÷ 122,3 − 1 = +8,5 % (PNB d’Ecobank CI en 2025)"},{"nom":"Taux de croissance annuel moyen (TCAM)","expression":"TCAM = (valeur finale ÷ valeur initiale)^(1/n) − 1","exemple":"(132,7 ÷ 90,5)^(1/4) − 1 = 10,0 % par an"}],"simulation":{"type":"croissance","consigne":"Reprenez le PNB d’Ecobank Côte d’Ivoire, puis remplacez par les chiffres d’une autre société : la croissance totale et le TCAM se recalculent.","valeur_initiale":90.5,"valeur_finale":132.7,"annees":4,"unite":"Md FCFA"}},{"type":"definition","titre":"Rentabilité : marge nette, ROE et ROA","contenu":"La marge nette rapporte le résultat net au chiffre d’affaires. Pour une banque, le produit net bancaire (PNB) remplace le chiffre d’affaires. Le ROE rapporte le résultat net aux capitaux propres, le ROA au total des actifs.\nLe ROE se calcule normalement sur les capitaux propres moyens, c’est-à-dire la moyenne entre le début et la fin de l’exercice. Faute de cette moyenne, un ROE calculé sur les capitaux propres de clôture reste indicatif : quand les capitaux propres augmentent dans l’année, il sous-estime légèrement le rendement réellement obtenu.\nExemple réel, Ecobank Côte d’Ivoire en 2025 : 63,5 milliards de résultat pour des capitaux propres passés de 199,4 à 218,6 milliards. ROE de clôture : 29,0 % ; ROE sur capitaux moyens : 30,4 %. Les deux chiffres sont justes ; ils ne se comparent qu’à méthode égale.","formules":[{"nom":"Marge nette","expression":"Marge nette = (résultat net ÷ chiffre d’affaires ou PNB) × 100","exemple":"63,5 ÷ 132,7 = 47,9 % (Ecobank CI, 2025)"},{"nom":"ROE","expression":"ROE = (résultat net ÷ capitaux propres moyens) × 100","exemple":"63,5 ÷ ((199,4 + 218,6) ÷ 2) = 30,4 %"},{"nom":"ROA","expression":"ROA = (résultat net ÷ total des actifs moyens) × 100","exemple":"63,5 ÷ ((2 050,7 + 2 054,5) ÷ 2) = 3,09 %"}],"simulation":{"type":"roe_moyen","consigne":"Les valeurs proposées sont celles d’Ecobank Côte d’Ivoire pour 2025. Modifiez les capitaux propres du début : l’écart entre les deux ROE apparaît.","resultat_net":63.5,"capitaux_debut":199.4,"capitaux_fin":218.6,"actif_debut":2050.7,"actif_fin":2054.5,"unite":"Md FCFA"}},{"type":"definition","titre":"Valorisation boursière : BPA, PER, P/B et rendement","contenu":"Le bénéfice par action (BPA) rapporte le résultat net attribuable aux actionnaires au nombre moyen pondéré d’actions. Le PER divise le cours par le BPA : il dit combien d’années de bénéfice actuel le marché paie. Le P/B compare le cours à la valeur comptable par action. Le rendement du dividende rapporte le dividende au cours.\nExemple réel : à la clôture 2025, l’action Société Générale Côte d’Ivoire valait 29 895 FCFA pour un BPA 2025 de 3 257,73 FCFA, soit un PER de 9,18. Au 23 novembre 2026, au cours de 3 900 FCFA, le dividende net 2025 de Sonatel (174 FCFA) représente un rendement de 4,46 %.\nDeux précautions. Le PER se calcule avec un cours et un bénéfice de la même période ; et pour un groupe qui a des filiales, il faut savoir si le BPA porte sur le résultat consolidé ou sur la seule part du groupe. Les calculateurs ci-dessous lisent aussi les données réelles en base.","formules":[{"nom":"BPA","expression":"BPA = résultat net attribuable aux actionnaires ÷ nombre moyen pondéré d’actions","exemple":"413,6 milliards ÷ 1 milliard d’actions = 413,60 FCFA (Sonatel 2025, après fractionnement)"},{"nom":"PER","expression":"PER = cours ÷ BPA, ou capitalisation ÷ résultat net","exemple":"29 895 ÷ 3 257,73 = 9,18 (SGBC, clôture 2025)"},{"nom":"P/B (price to book)","expression":"P/B = cours ÷ valeur comptable par action","exemple":"Ecobank CI au 23/11/2026 : 14 455 ÷ (218,6 milliards ÷ 55,05 millions d’actions) = 3,64"},{"nom":"Rendement du dividende","expression":"Rendement = (dividende par action ÷ cours) × 100","exemple":"174 ÷ 3 900 = 4,46 % (Sonatel, dividende net 2025)"}],"simulations":[{"type":"per","consigne":"Le PER de Sonatel au 23/11/2026, sur le BPA consolidé 2025. La croissance de 5 % par an est une hypothèse à modifier, pas une prévision. Choisissez une valeur pour passer aux données réelles.","cours":3900,"bpa":413.6,"croissance_pct":5,"annees":3,"codes":["SNTS","ORAC","ECOC","SGBC"]},{"type":"pb_roe","consigne":"P/B = PER × ROE : les deux opérateurs de télécommunications au 23/11/2026, sur les comptes 2025.","societes":[{"nom":"Sonatel (SNTS)","per":9.4,"roe_pct":29.6},{"nom":"Orange CI (ORAC)","per":17.1,"roe_pct":23.7}],"codes":["SNTS","ORAC"]}]},{"type":"definition","titre":"Endettement et solvabilité des entreprises non financières","contenu":"La dette financière nette retranche la trésorerie des emprunts. Le gearing la rapporte aux capitaux propres ; la couverture des intérêts dit combien de fois le résultat opérationnel paie les charges financières.\nUne dette nette négative signifie que l’entreprise détient plus de trésorerie qu’elle ne doit d’emprunts. Selon S&P Global, Sonatel est ainsi passée d’une trésorerie nette (une dette nette de −199 milliards en 2021) à une dette nette de 133 milliards en 2025, pendant que ses investissements annuels passaient de 221 à 318 milliards.","formules":[{"nom":"Dette financière nette","expression":"Dette nette = emprunts et dettes financières − trésorerie"},{"nom":"Gearing","expression":"Gearing = (dette nette ÷ capitaux propres) × 100"},{"nom":"Couverture des intérêts","expression":"Couverture = résultat opérationnel ÷ charges d’intérêts"}],"simulation":{"type":"endettement","consigne":"Exemple fictif d’entreprise industrielle : modifiez la trésorerie ou les charges d’intérêts et observez le gearing et la couverture.","dettes_financieres":300,"tresorerie":100,"capitaux_propres":400,"resultat_operationnel":120,"charges_interets":20,"unite":"Md FCFA"},"encadres":[{"ton":"alerte","titre":"Important pour les banques","texte":"Les ratios de dette nette, de gearing et d’EV/EBITDA sont inadaptés aux banques. Leur bilan est fait de dépôts, de crédits et de placements : la dette y est la matière première. Pour une banque, on examine plutôt la qualité des actifs, les créances en souffrance, le coût du risque, le ratio de solvabilité, le ROE et le P/B (leçon 0.3)."}]},{"type":"retenir","titre":"L’essentiel","contenu":"Chaque ratio répond à une question précise, et chacun a ses pièges de calcul : le nombre d’années du TCAM, les capitaux propres moyens du ROE, la même période pour le cours et le bénéfice du PER, le périmètre consolidé ou part du groupe du BPA.","points":[{"titre":"Croissance","detail":"Annuelle pour suivre le rythme, TCAM pour comparer des trajectoires."},{"titre":"Rentabilité","detail":"Marge, ROE et ROA, à méthode identique d’une société à l’autre."},{"titre":"Valorisation","detail":"PER, P/B et rendement, toujours datés et sourcés."},{"titre":"Endettement","detail":"Dette nette, gearing et couverture, jamais pour une banque."}]}],"quiz":[{"question":"Un chiffre d’affaires passe de 100 à 146,4 en quatre ans. Quel est le TCAM ?","options":["10 %","11,6 %","9,2 %","46,4 %"],"correct":0,"explication":"(146,4 ÷ 100)^(1/4) − 1 = 1,10 − 1 = 10 % par an. 46,4 % est la croissance totale, pas annuelle."},{"question":"Résultat net 60, capitaux propres 200 au début et 240 à la fin de l’exercice. Quel est le ROE sur capitaux moyens ?","options":["25,0 %","27,3 %","30,0 %","22,0 %"],"correct":1,"explication":"Capitaux moyens = (200 + 240) ÷ 2 = 220 ; 60 ÷ 220 = 27,3 %. Sur la seule clôture, on trouverait 25,0 %."},{"question":"Une action cote 12 000 FCFA pour un BPA de 1 500 FCFA. Quel est son PER ?","options":["6","8","12","18"],"correct":1,"explication":"12 000 ÷ 1 500 = 8 : le marché paie huit années du bénéfice actuel."},{"question":"Dettes financières 300, trésorerie 100, capitaux propres 400. Quel est le gearing ?","options":["75 %","100 %","50 %","25 %"],"correct":2,"explication":"Dette nette = 300 − 100 = 200 ; 200 ÷ 400 = 50 %."},{"question":"Pourquoi n’applique-t-on pas le gearing à une banque ?","options":["Parce qu’une banque n’a jamais de capitaux propres au bilan","Parce que ses dépôts sont une dette par nature","Parce que les banques ne publient aucun bilan détaillé","Parce que le gearing d’une banque est toujours égal à zéro"],"correct":1,"explication":"Les dépôts de la clientèle figurent au passif comme une dette : rapporter cette « dette » aux capitaux propres ne dit rien du risque de la banque."}],"qcm":{"question":"Un chiffre d’affaires passe de 100 à 146,4 en quatre ans. Quel est le TCAM ?","options":["10 %","11,6 %","9,2 %","46,4 %"],"correct":0,"explication":"(146,4 ÷ 100)^(1/4) − 1 = 1,10 − 1 = 10 % par an. 46,4 % est la croissance totale, pas annuelle."},"liens":[{"label":"La valorisation de toutes les valeurs","href":"/premium/valorisation"},{"label":"Comparer des actions","href":"/actions/compare"},{"label":"Le screener","href":"/screener"}],"avertissement":"Ceci n’est pas un conseil en investissement. Les ratios décrivent le passé et ne garantissent aucune performance future. Investir en actions comporte un risque de perte en capital."},{"titre":"Leçon 0.3 — Analyser une banque cotée","module":"Module 0 — Le cours complet : analyse fondamentale appliquée à la BRVM","categorie":"fundamental","duree_min":14,"sous_titre":"PNB, coût du risque, créances en souffrance, couverture, coefficient d’exploitation, solvabilité : les indicateurs propres aux banques.","resume":"Les banques représentent une part majeure de la capitalisation de la BRVM. Leur analyse exige des indicateurs qui n’ont pas d’équivalent dans l’industrie : le produit net bancaire tient lieu de chiffre d’affaires, le coût du risque mesure la qualité des crédits, et le ratio de solvabilité borne ce que la banque peut prêter. Cette leçon les définit, montre le chemin du crédit accordé au résultat net, et affiche les ratios réels des banques cotées.","nouveaute":{"type":"nouveau","depuis":"2026-11-24"},"sections":[{"type":"definition","titre":"Pourquoi une banque se lit à part","contenu":"Une banque vend de l’argent : elle collecte des dépôts, qu’elle prête à un taux plus élevé. Son bilan est fait de dépôts au passif et de crédits à l’actif, et son « chiffre d’affaires » est un écart de taux, complété par des commissions.\nLes banques représentent une part majeure de la capitalisation de la BRVM. Leur analyse exige donc des indicateurs spécifiques, qui n’ont pas d’équivalent dans l’industrie classique, et elle se lit toujours avec la qualité du portefeuille de crédits : c’est là que se loge le risque."},{"type":"importance","titre":"Les sept indicateurs d’une banque","contenu":"Le tableau réunit les indicateurs à suivre, ce qu’ils mesurent et la lecture qui en découle. La plupart sont publiés par les banques elles-mêmes dans leur rapport d’activité ; le ratio de solvabilité est un ratio réglementaire, contrôlé par la Commission bancaire de l’UMOA.\nAppliqués aux deux banques étudiées ensuite, ces indicateurs donnent déjà des repères. En 2025, Société Générale Côte d’Ivoire prête 87,6 % de ses dépôts à sa clientèle, Ecobank Côte d’Ivoire 64,6 %. Un rapport élevé n’est pas un défaut en soi : la banque transforme une plus grande part de ses ressources en crédits, ce qui lui rapporte davantage d’intérêts et l’expose davantage au risque de crédit.\nCôté efficacité, Sika Finance donne pour Société Générale Côte d’Ivoire un coefficient d’exploitation de 36,8 % sur les neuf premiers mois de 2026 : sur 100 francs de PNB, environ 37 paient les frais généraux. Côté solvabilité, la même banque affiche 17,6 % au premier semestre 2026, pour un minimum réglementaire de 11,5 %.","tableau":{"colonnes":["Indicateur bancaire","Définition","Pourquoi c’est important"],"lignes":[["Produit net bancaire (PNB)","Revenus d’intérêts, commissions et autres produits, nets des charges correspondantes, avant le coût du risque.","Équivalent du chiffre d’affaires pour une banque : il mesure l’activité globale."],["Coût du risque","Dotations aux provisions pour créances en souffrance, nettes des reprises.","Il traduit la qualité du portefeuille de crédits ; un coût du risque faible et stable est un signal positif."],["Créances en souffrance (NPL)","Encours de crédits dont le remboursement est retardé ou compromis.","Plus leur part est élevée, plus le risque de crédit est important."],["Taux de couverture","Provisions ÷ créances en souffrance : la part des pertes potentielles déjà provisionnée.","Un taux élevé, de l’ordre de 80 % ou plus, traduit une approche prudente."],["Coefficient d’exploitation","Frais généraux ÷ PNB : l’efficacité opérationnelle.","Plus il est bas, plus la banque est efficace ; sous 50 %, il est généralement jugé très bon."],["Ratio de solvabilité","Fonds propres ÷ actifs pondérés par leur risque. Minimum réglementaire de l’UMOA : 11,5 % depuis 2023 (rapports annuels de la BCEAO).","Un ratio élevé donne une marge de sécurité réglementaire et de la capacité à prêter."],["Ratio crédits ÷ dépôts","Crédits nets à la clientèle ÷ dépôts de la clientèle.","Il indique si la banque finance ses crédits par les ressources qu’elle collecte."]],"note":"Ratio de solvabilité total minimum de 11,5 % depuis la fin de la période transitoire, en 2023 (11,25 % à fin 2022). Le cours fourni citait 12,5 % pour les banques d’importance systémique (EBIS) : ce seuil n’apparaît pas dans les rapports consultés."}},{"type":"importance","titre":"Du crédit accordé au résultat net","contenu":"Tout part d’un crédit. S’il est remboursé normalement, il produit des intérêts qui alimentent le PNB puis le résultat. S’il ne l’est pas, il devient une créance en souffrance, que la banque doit provisionner : la provision passe en coût du risque et réduit le résultat net, puis les fonds propres.\nC’est pourquoi une banque peut afficher un bénéfice élevé une année et le voir fondre la suivante : il suffit que des crédits accordés trop facilement se dégradent. Le cas d’Ecobank Côte d’Ivoire en 2026, étudié à la leçon 0.4, en donne un exemple mesuré.","flux":[{"titre":"Crédit accordé","detail":"La banque prête l’argent de ses dépôts.","icone":"paiement"},{"titre":"Remboursement régulier ?","detail":"Le client paie ses échéances.","icone":"decision"},{"titre":"Intérêts → PNB → résultat","detail":"Si oui : l’écart de taux devient du résultat.","icone":"benefices"}],"etapes":[{"titre":"Sinon : créance en souffrance","detail":"Le remboursement est retardé ou compromis."},{"titre":"Provision, puis coût du risque","detail":"La banque anticipe la perte et la passe en charge.","cle":true},{"titre":"Impact sur le résultat net et les fonds propres","detail":"Moins de résultat, donc moins de réserves et de dividende."}],"encadres":[{"ton":"cle","titre":"Lecture clé","texte":"Une banque peut afficher un bénéfice élevé tout en portant des risques cachés sur ses crédits. Le résultat net doit toujours être lu avec la qualité des actifs, le coût du risque et le niveau de provisionnement."}]},{"type":"cas","titre":"Calculateur : ce que les frais et le coût du risque laissent à la banque","contenu":"Exemple fictif : une banque dégage 100 milliards de PNB, dépense 45 milliards de frais généraux et provisionne 5 milliards. Faites varier le coût du risque pour voir ce qu’il retire au résultat avant impôt.","simulation":{"type":"banque","consigne":"Doublez le coût du risque : l’effet sur le résultat avant impôt est immédiat.","pnb":100,"frais_generaux":45,"cout_risque":5,"unite":"Md FCFA"}},{"type":"cas","titre":"Les banques de la BRVM, en direct","reel":true,"contenu":"Les ratios ci-dessous sont recalculés au chargement de la leçon, sur le dernier exercice publié et le dernier cours connu en base. Ils ne sont donc pas figés à la date de rédaction : comparez-les à ceux du 23 novembre 2026 cités dans les leçons 0.4 à 0.6.","donnees_reelles":{"vue":"ratios","codes":["ECOC","SGBC","SIBC","BOAC","NSBC","BICC"]}},{"type":"retenir","titre":"L’essentiel","contenu":"Une banque se lit avec ses propres indicateurs : le PNB pour l’activité, le coefficient d’exploitation pour l’efficacité, le coût du risque, les créances en souffrance et leur couverture pour la qualité des crédits, et le ratio de solvabilité pour la marge réglementaire.","points":[{"titre":"Le risque est dans les crédits","detail":"Coût du risque et couverture se lisent avant le résultat net."},{"titre":"Solvabilité : 11,5 % au minimum","detail":"Ratio de solvabilité total de l’UMOA depuis 2023."},{"titre":"Pas de gearing pour une banque","detail":"Les dépôts sont une dette par nature."}]}],"quiz":[{"question":"Que mesure le coefficient d’exploitation d’une banque ?","options":["La part des crédits en souffrance","Les frais généraux rapportés au PNB","Les fonds propres rapportés aux actifs","Les dépôts rapportés aux crédits"],"correct":1,"explication":"Frais généraux ÷ PNB : plus il est bas, plus la banque transforme son activité en résultat."},{"question":"PNB 100, frais généraux 45, coût du risque 5. Quel est le résultat avant impôt ?","options":["55","50","45","60"],"correct":1,"explication":"100 − 45 = 55 de résultat brut d’exploitation, moins 5 de coût du risque : 50."},{"question":"Quel est le ratio de solvabilité total minimum dans l’UMOA depuis 2023 ?","options":["8,0 %","10,0 %","11,5 %","12,5 %"],"correct":2,"explication":"Les rapports annuels de la BCEAO donnent 11,5 % depuis la fin de la période transitoire (11,25 % à fin 2022)."},{"question":"Une banque a 40 de créances en souffrance et 36 de provisions. Quel est son taux de couverture ?","options":["80 %","111 %","90 %","36 %"],"correct":2,"explication":"36 ÷ 40 = 90 % : neuf dixièmes des pertes potentielles sont déjà provisionnés."},{"question":"Pourquoi un bénéfice bancaire élevé ne suffit-il pas à juger une banque ?","options":["Parce qu’il peut masquer des crédits qui se dégradent","Parce que les banques ne paient pas d’impôt","Parce que le PNB n’est jamais publié","Parce que le bénéfice d’une banque est toujours exceptionnel"],"correct":0,"explication":"Le coût du risque et les créances en souffrance disent si le bénéfice tiendra : un portefeuille qui se dégrade finit par peser sur le résultat."}],"qcm":{"question":"Que mesure le coefficient d’exploitation d’une banque ?","options":["La part des crédits en souffrance","Les frais généraux rapportés au PNB","Les fonds propres rapportés aux actifs","Les dépôts rapportés aux crédits"],"correct":1,"explication":"Frais généraux ÷ PNB : plus il est bas, plus la banque transforme son activité en résultat."},"liens":[{"label":"Les secteurs","href":"/secteurs"},{"label":"Comparer des actions","href":"/actions/compare"},{"label":"La valorisation de toutes les valeurs","href":"/premium/valorisation"}],"avertissement":"Ceci n’est pas un conseil en investissement. Les ratios décrivent le passé et ne garantissent aucune performance future. Investir en actions comporte un risque de perte en capital."},{"titre":"Leçon 0.4 — Cas réel : Ecobank Côte d’Ivoire (ECOC)","module":"Module 0 — Le cours complet : analyse fondamentale appliquée à la BRVM","categorie":"fundamental","duree_min":18,"sous_titre":"Cinq exercices de comptes, le cours, le PER et le dividende, puis les comptes de 2026 : une banque très rentable face à un provisionnement en hausse.","resume":"Filiale d’Ecobank Transnational Incorporated (ETI), cotée à la BRVM depuis décembre 2017, Ecobank Côte d’Ivoire affiche un ROE de 29,0 % en 2025 sur ses capitaux propres de clôture. Cette leçon reprend ses comptes 2021-2025 tels qu’ils sont publiés, recalcule chaque ratio, compare deux séries de PNB, puis lit les comptes de 2026 : la hausse du coût du risque y fait reculer le résultat.","nouveaute":{"type":"nouveau","depuis":"2026-11-24"},"sections":[{"type":"cas","titre":"La fiche au 23 novembre 2026","reel":true,"contenu":"Au 23 novembre 2026, l’action Ecobank Côte d’Ivoire cotait 14 455 FCFA, en recul de 2,30 % sur la séance. Avec 55,05 millions d’actions, la capitalisation atteint 795,8 milliards de FCFA.\nSur le BPA de l’exercice 2025 (1 153,16 FCFA), le PER ressort à 12,54. StockAnalysis affiche 14,04 sur douze mois glissants : ce PER intègre les trimestres de 2026, où le résultat recule. Le dividende brut 2025 de 888 FCFA représente 6,14 % du cours, soit 5,41 % après retenue à la source.\nDepuis le 1er janvier 2026, le titre perd 9,66 % ; sur un an (depuis le 24/11/2025), 5,52 %. Sur trois ans (depuis le 23/11/2023), il a gagné 107,2 %. Le bloc en direct, en bas de section, recalcule ces ratios sur les derniers chiffres disponibles.","stats":[{"label":"Cours au 23/11/2026","valeur":"14 455 FCFA","detail":"−2,30 % sur la séance"},{"label":"Capitalisation","valeur":"795,8 Md FCFA","detail":"55,05 millions d’actions"},{"label":"PER sur le BPA 2025","valeur":"12,54","detail":"14,04 sur 12 mois glissants (StockAnalysis)"},{"label":"Rendement du dividende 2025","valeur":"6,14 %","detail":"brut ; 5,41 % net"},{"label":"Depuis le 1er janvier","valeur":"−9,66 %","detail":"sur un an : −5,52 %"},{"label":"Bêta sur un an","valeur":"0,64","detail":"StockAnalysis / S&P Global"}],"donnees_reelles":{"vue":"ratios","codes":["ECOC"]}},{"type":"cas","titre":"Les comptes 2021-2025, recalculés","reel":true,"contenu":"Le tableau reprend les comptes publiés et recalcule chaque ratio. Le PNB passe de 90,5 à 132,7 milliards de FCFA, soit un TCAM de 10,0 % ; le résultat net, de 34,3 à 63,5 milliards, soit 16,6 % par an. Le résultat croît plus vite que l’activité : la marge nette gagne 10,0 points en quatre ans.\nDeux séries de PNB circulent. Celle des comptes publiés, ici en première ligne, et celle de S&P Global / StockAnalysis, qui standardise les postes pour comparer des banques du monde entier. Elles concordent pour 2025 (132,7 milliards) et divergent avant, signe que les deux séries ne retiennent pas les mêmes postes. Pour suivre une banque dans le temps, gardez une seule série.\nLe rendement est ici calculé à la clôture de l’exercice : dividende de l’année divisé par le dernier cours de l’année. D’autres sites le calculent sur le dividende versé dans l’année ou sur un cours moyen, d’où des chiffres différents pour une même année.","tableau":{"colonnes":["Indicateur","2021","2022","2023","2024","2025"],"lignes":[["Produit net bancaire, comptes publiés (Md FCFA)","90,5","99,2","110,2","122,3","132,7"],["Croissance du PNB","—","+9,6 %","+11,1 %","+11,0 %","+8,5 %"],["PNB, série standardisée S&P / StockAnalysis (Md FCFA)","—","94,5","104,2","119,4","132,7"],["Résultat net (Md FCFA)","34,3","44,6","48,1","57,5","63,5"],["Croissance du résultat net","—","+30,0 %","+7,8 %","+19,5 %","+10,4 %"],["Total du bilan (Md FCFA)","1 677,7","1 901,2","1 953,3","2 050,7","2 054,5"],["Capitaux propres (Md FCFA)","144,8","163,7","178,2","199,4","218,6"],["Dépôts de la clientèle (Md FCFA)","—","—","—","1 412,5","1 626,2"],["Crédits à la clientèle (Md FCFA)","—","—","—","972,6","1 050,8"],["Crédits ÷ dépôts","—","—","—","68,9 %","64,6 %"],["ROE sur capitaux propres de clôture","23,7 %","27,2 %","27,0 %","28,8 %","29,0 %"],["ROE sur capitaux propres moyens","—","28,9 %","28,1 %","30,5 %","30,4 %"],["Marge nette (résultat net ÷ PNB)","37,9 %","45,0 %","43,6 %","47,0 %","47,9 %"],["BPA (FCFA)","623,14","810,13","873,00","1 044,00","1 153,16"],["Cours de clôture de l’année (FCFA)","4 785","4 945","6 800","8 795","16 000"],["PER à la clôture de l’année","7,68","6,10","7,79","8,42","13,87"],["Dividende par action publié (FCFA)","420,30","549,00","594,00","708,00","888 brut / 781,44 net"],["Rendement à la clôture de l’année","8,8 %","11,1 %","8,7 %","8,1 %","5,5 %"]],"note":"Dividende : montant publié par exercice ; la base fiscale (brut ou net d’impôt) n’est connue avec certitude que pour 2025, d’après le calendrier de paiement des dividendes de la BRVM. Rendement à la clôture = dividende publié de l’exercice ÷ dernier cours de l’année. « — » : donnée absente de la source."},"graphiques":[{"type":"bar","titre":"Ecobank CI : PNB et résultat net (2021-2025, Md FCFA)","labels":["2021","2022","2023","2024","2025"],"unite":"Md FCFA","note":"Le résultat net progresse de 85,1 % en quatre ans, le PNB de 46,6 %. Sources : états financiers publiés (base WESTBOURSE) et clôtures de la BRVM, exercices 2021 à 2025, lus le 24/11/2026 ; calculs WESTBOURSE.","reel":true,"series":[{"nom":"PNB","valeurs":[90.5,99.2,110.2,122.3,132.7]},{"nom":"Résultat net","valeurs":[34.3,44.6,48.1,57.5,63.5]}]},{"type":"bar","titre":"Ecobank CI : cours de clôture de l’année et PER (2021-2025)","labels":["2021","2022","2023","2024","2025"],"unite":"FCFA","note":"Le PER passe de 7,68 à 13,87 : le cours a monté plus vite que le bénéfice. Cliquez sur la légende pour masquer une série. Sources : états financiers publiés (base WESTBOURSE) et clôtures de la BRVM, exercices 2021 à 2025, lus le 24/11/2026 ; calculs WESTBOURSE.","reel":true,"series":[{"nom":"Cours de clôture (FCFA)","valeurs":[4785,4945,6800,8795,16000]},{"nom":"PER","valeurs":[7.68,6.1,7.79,8.42,13.87],"type":"line","axe":"droite"}],"unite_droite":"x"},{"type":"bar","titre":"Ecobank CI : dividende par action publié (FCFA, exercices 2021-2025)","labels":["2021","2022","2023","2024","2025"],"unite":"FCFA","note":"Dividende de l’exercice tel que publié ; 2025 : 888 FCFA brut, 781,44 FCFA net. Sources : états financiers publiés (base WESTBOURSE) et clôtures de la BRVM, exercices 2021 à 2025, lus le 24/11/2026 ; calculs WESTBOURSE.","reel":true,"valeurs":[420.3,549,594,708,888]}],"donnees_reelles":{"vue":"historique","codes":["ECOC"]}},{"type":"cas","titre":"2026 : les comptes intermédiaires","reel":true,"contenu":"Les comptes de 2026 ne sont pas audités. Le PNB continue de progresser (+2,1 % au premier semestre), mais le résultat net recule : −8,7 % au premier semestre, et −11,0 % sur neuf mois si l’on rapporte le chiffre de Sika Finance (environ 39,5 milliards) aux 44,4 milliards de neuf mois 2025 en base. Sika Finance annonce −12,3 %.\nLa cause est connue : un provisionnement renforcé. Selon Sika Finance, le coût du risque atteint 5,2 milliards au premier semestre 2026, contre 0,7 milliard un an plus tôt. Le taux de couverture des créances en souffrance avoisine 90 % à fin juin 2026, après un coût du risque de seulement 0,2 % en 2025.","tableau":{"colonnes":["Période 2026","PNB (Md FCFA)","Variation","Résultat net (Md FCFA)","Variation","Source"],"lignes":[["1er trimestre (31 mars)","30,8","+3,7 %","13,0","−2,3 %","Base WESTBOURSE"],["1er semestre (30 juin)","64,1","+2,1 %","26,4","−8,7 %","Base WESTBOURSE ; total du bilan ≈ 2 078 Md (Sika Finance)"],["9 premiers mois (30 sept.)","98,2","+1,9 %","≈ 39,5","−11,0 %","Sika Finance, articles du 30/04/2026, 10/09/2026 et 28/10/2026"]],"note":"Comptes non audités. Variations calculées par rapport à la même période de 2025, en base. Les comptes intermédiaires sont des cumuls depuis le 1er janvier."},"donnees_reelles":{"vue":"cours","codes":["ECOC"],"actions":10}},{"type":"importance","titre":"La lecture d’Ecobank Côte d’Ivoire","contenu":"Croissance : le PNB progresse chaque année, de 10,0 % par an en moyenne de 2021 à 2025, et le résultat net plus vite encore, de 16,6 % par an.\nRentabilité : ROE de 29,0 % sur les capitaux de clôture 2025, 30,4 % sur les capitaux moyens ; comparez-le aux autres banques cotées dans le bloc en direct de la leçon 0.3. La marge nette atteint 48 % du PNB en 2025.\nRisque : un coût du risque très faible en 2025, puis un provisionnement nettement renforcé en 2026, qui explique le recul du résultat. Valorisation : le PER de fin d’année passe de 7,68 en 2021 à 13,87 en 2025 ; le cours a été réévalué plus vite que le bénéfice, puis il recule en 2026 (−9,7 % depuis le 1er janvier).","simulation":{"type":"per","consigne":"Le PER d’Ecobank CI au 23/11/2026, sur le BPA 2025. Passez aux données réelles pour le recalculer au dernier cours.","cours":14455,"bpa":1153.16,"croissance_pct":0,"annees":3,"codes":["ECOC"]}},{"type":"retenir","titre":"L’essentiel","contenu":"Ecobank Côte d’Ivoire illustre une banque très rentable dont le résultat dépend, à court terme, de son provisionnement. Ses chiffres se lisent avec une seule série de PNB, un ROE à méthode constante et un dividende dont on connaît la base fiscale.","points":[{"titre":"Une série, une méthode","detail":"Comptes publiés et base standardisée divergent : ne les mélangez pas."},{"titre":"Le coût du risque fait le résultat","detail":"En 2026, il fait reculer le bénéfice malgré un PNB en hausse."},{"titre":"Un PER qui a presque doublé","detail":"La réévaluation du cours a précédé le bénéfice."}]}],"quiz":[{"question":"Le PNB d’Ecobank CI passe de 90,5 à 132,7 milliards entre 2021 et 2025. Quel est le TCAM ?","options":["10,0 %","46,6 %","9,3 %","8,5 %"],"correct":0,"explication":"(132,7 ÷ 90,5)^(1/4) − 1 = 10,0 %. 46,6 % est la croissance totale."},{"question":"Cours de clôture 2025 : 16 000 FCFA ; BPA 2025 : 1 153,16 FCFA. Quel est le PER ?","options":["12,54","13,87","8,42","16,65"],"correct":1,"explication":"16 000 ÷ 1 153,16 = 13,87."},{"question":"Pourquoi le résultat net d’Ecobank CI recule-t-il en 2026 alors que le PNB progresse ?","options":["Parce que le nombre d’actions a doublé après une augmentation de capital","Parce que le coût du risque a fortement augmenté","Parce que la banque a cessé de prêter","Parce que le PNB n’est pas publié en 2026"],"correct":1,"explication":"Le coût du risque passe de 0,7 à 5,2 milliards d’un premier semestre à l’autre (Sika Finance) : un provisionnement prudent pèse sur le résultat."},{"question":"Le dividende 2025 est de 888 FCFA brut. Au cours de 14 455 FCFA, quel est le rendement brut ?","options":["5,41 %","5,55 %","6,14 %","9,21 %"],"correct":2,"explication":"888 ÷ 14 455 = 6,14 % ; net de la retenue à la source, 5,41 %."},{"question":"Deux séries de PNB d’Ecobank CI circulent pour 2022-2024. Que faire pour suivre la banque dans le temps ?","options":["Prendre chaque année la série la plus favorable","Additionner les deux séries","Ignorer le PNB et ne regarder que le cours","Garder une seule série, avec sa définition"],"correct":3,"explication":"Comptes publiés et base standardisée n’ont pas la même définition : mélanger les deux fabriquerait une croissance fausse."}],"qcm":{"question":"Le PNB d’Ecobank CI passe de 90,5 à 132,7 milliards entre 2021 et 2025. Quel est le TCAM ?","options":["10,0 %","46,6 %","9,3 %","8,5 %"],"correct":0,"explication":"(132,7 ÷ 90,5)^(1/4) − 1 = 10,0 %. 46,6 % est la croissance totale."},"liens":[{"label":"Les fiches sociétés","href":"/societes"},{"label":"Les dividendes","href":"/dividendes"},{"label":"Comparer des actions","href":"/actions/compare"}],"avertissement":"Ceci n’est pas un conseil en investissement. Les ratios décrivent le passé et ne garantissent aucune performance future. Investir en actions comporte un risque de perte en capital."},{"titre":"Leçon 0.5 — Cas réel : Société Générale Côte d’Ivoire (SGBC)","module":"Module 0 — Le cours complet : analyse fondamentale appliquée à la BRVM","categorie":"fundamental","duree_min":18,"sous_titre":"La plus grande banque du cas : croissance qui ralentit, capitaux propres renforcés, solvabilité confortable et un dividende 2025 en forte hausse.","resume":"Filiale du groupe Société Générale, présent en Côte d’Ivoire depuis 1941 selon la banque, Société Générale Côte d’Ivoire est la plus grande des deux banques étudiées : 276,0 milliards de PNB et 3 769,2 milliards de bilan en 2025. Cette leçon reprend ses comptes 2021-2025, recalcule les ratios, explique pourquoi une autre série de PNB, plus élevée, circule, puis lit les comptes de 2026.","nouveaute":{"type":"nouveau","depuis":"2026-11-24"},"sections":[{"type":"cas","titre":"La fiche au 23 novembre 2026","reel":true,"contenu":"Au 23 novembre 2026, l’action Société Générale Côte d’Ivoire cotait 37 610 FCFA, en recul de 3,05 % sur la séance. Avec 31,11 millions d’actions, la capitalisation atteint 1 170,1 milliards de FCFA.\nSur le BPA 2025 (3 257,73 FCFA), le PER ressort à 11,54 ; StockAnalysis affiche 12,26 sur douze mois glissants. Le dividende brut 2025, 2 606 FCFA, représente 6,93 % du cours, 6,10 % net.\nLe titre gagne 25,81 % depuis le 1er janvier 2026 et 36,0 % sur un an (depuis le 24/11/2025) : le marché l’a nettement réévalué.","stats":[{"label":"Cours au 23/11/2026","valeur":"37 610 FCFA","detail":"−3,05 % sur la séance"},{"label":"Capitalisation","valeur":"1 170,1 Md FCFA","detail":"31,11 millions d’actions"},{"label":"PER sur le BPA 2025","valeur":"11,54","detail":"12,26 sur 12 mois glissants (StockAnalysis)"},{"label":"Rendement du dividende 2025","valeur":"6,93 %","detail":"brut ; 6,10 % net"},{"label":"Depuis le 1er janvier","valeur":"+25,81 %","detail":"sur un an : +36,0 %"},{"label":"Bêta sur un an","valeur":"0,68","detail":"StockAnalysis / S&P Global"}],"donnees_reelles":{"vue":"ratios","codes":["SGBC"]}},{"type":"cas","titre":"Les comptes 2021-2025, recalculés","reel":true,"contenu":"Le PNB publié passe de 189,1 à 276,0 milliards de FCFA, soit 9,9 % par an ; le résultat net, de 67,4 à 101,4 milliards, soit 10,8 % par an. Mais la croissance ralentit nettement : +0,2 % seulement pour le résultat 2025.\nUne série plus élevée circule, de 233,2 à 333,5 milliards : c’est la série standardisée de S&P Global / StockAnalysis, qui ne retient pas le même périmètre. Les comptes intermédiaires tranchent : 201,0 milliards de PNB sur neuf mois 2025, soit un rythme annuel proche des 276,0 milliards publiés, pas des 333,5.\nLes capitaux propres augmentent fortement, de 451,7 à 495,1 milliards en 2025 : le ROE de clôture baisse à 20,5 %, alors que le résultat est stable. C’est l’effet mécanique d’un dénominateur qui grossit.","tableau":{"colonnes":["Indicateur","2021","2022","2023","2024","2025"],"lignes":[["Produit net bancaire, comptes publiés (Md FCFA)","189,1","215,1","253,3","263,2","276,0"],["Croissance du PNB","—","+13,7 %","+17,8 %","+3,9 %","+4,9 %"],["PNB, série standardisée S&P / StockAnalysis (Md FCFA)","233,2","265,8","304,2","321,5","333,5"],["Résultat net (Md FCFA)","67,4","74,6","97,2","101,2","101,4"],["Croissance du résultat net","—","+10,7 %","+30,3 %","+4,1 %","+0,2 %"],["Total du bilan (Md FCFA)","3 021,5","3 345,3","3 437,7","3 614,2","3 769,2"],["Capitaux propres (Md FCFA)","305,0","345,0","404,0","451,7","495,1"],["Dépôts de la clientèle (Md FCFA)","—","—","—","2 747,5","2 907,7"],["Crédits à la clientèle (Md FCFA)","—","—","—","2 474,6","2 546,3"],["Crédits ÷ dépôts","—","—","—","90,1 %","87,6 %"],["ROE sur capitaux propres de clôture","22,1 %","21,6 %","24,1 %","22,4 %","20,5 %"],["ROE sur capitaux propres moyens","—","23,0 %","26,0 %","23,7 %","21,4 %"],["Marge nette (résultat net ÷ PNB)","35,6 %","34,7 %","38,4 %","38,4 %","36,7 %"],["BPA (FCFA)","2 167,65","2 398,23","3 125,00","3 254,00","3 257,73"],["Cours de clôture de l’année (FCFA)","10 595","11 605","16 050","21 000","29 895"],["PER à la clôture de l’année","4,89","4,84","5,14","6,45","9,18"],["Dividende par action publié (FCFA)","1 004,93","1 107,00","1 547,00","1 639,00","2 606 brut / 2 293,28 net"],["Rendement à la clôture de l’année","9,5 %","9,5 %","9,6 %","7,8 %","8,7 %"]],"note":"Dividende : montant publié par exercice ; la base fiscale (brut ou net d’impôt) n’est connue avec certitude que pour 2025, d’après le calendrier de paiement des dividendes de la BRVM. Rendement à la clôture = dividende publié de l’exercice ÷ dernier cours de l’année. « — » : donnée absente de la source."},"graphiques":[{"type":"bar","titre":"Société Générale CI : PNB et résultat net (2021-2025, Md FCFA)","labels":["2021","2022","2023","2024","2025"],"unite":"Md FCFA","note":"Le résultat net progresse de 50,4 % en quatre ans, le PNB de 46,0 %. Sources : états financiers publiés (base WESTBOURSE) et clôtures de la BRVM, exercices 2021 à 2025, lus le 24/11/2026 ; calculs WESTBOURSE.","reel":true,"series":[{"nom":"PNB","valeurs":[189.1,215.1,253.3,263.2,276]},{"nom":"Résultat net","valeurs":[67.4,74.6,97.2,101.2,101.4]}]},{"type":"bar","titre":"Société Générale CI : cours de clôture de l’année et PER (2021-2025)","labels":["2021","2022","2023","2024","2025"],"unite":"FCFA","note":"Le PER passe de 4,89 à 9,18 : le cours a monté plus vite que le bénéfice. Cliquez sur la légende pour masquer une série. Sources : états financiers publiés (base WESTBOURSE) et clôtures de la BRVM, exercices 2021 à 2025, lus le 24/11/2026 ; calculs WESTBOURSE.","reel":true,"series":[{"nom":"Cours de clôture (FCFA)","valeurs":[10595,11605,16050,21000,29895]},{"nom":"PER","valeurs":[4.89,4.84,5.14,6.45,9.18],"type":"line","axe":"droite"}],"unite_droite":"x"},{"type":"bar","titre":"Société Générale CI : dividende par action publié (FCFA, exercices 2021-2025)","labels":["2021","2022","2023","2024","2025"],"unite":"FCFA","note":"Dividende de l’exercice tel que publié ; 2025 : 2 606 FCFA brut, 2 293,28 FCFA net. Sources : états financiers publiés (base WESTBOURSE) et clôtures de la BRVM, exercices 2021 à 2025, lus le 24/11/2026 ; calculs WESTBOURSE.","reel":true,"valeurs":[1004.93,1107,1547,1639,2606]}],"donnees_reelles":{"vue":"historique","codes":["SGBC"]}},{"type":"cas","titre":"2026 : les comptes intermédiaires","reel":true,"contenu":"Le premier semestre 2026 est stable : PNB +1,6 %, résultat net +0,6 %. Sur neuf mois, selon Sika Finance, le PNB recule à 197,6 milliards (−1,7 % par rapport aux neuf mois 2025 en base) et le résultat net à 80,4 milliards (−3,5 %).\nLe bilan franchit 4 000 milliards au premier semestre (4 054,5 milliards), les capitaux propres atteignent 548,5 milliards (+22,7 % sur un an) et le ratio de solvabilité 17,6 %, bien au-dessus du minimum de 11,5 %. Le coefficient d’exploitation reste bas, 36,8 % sur neuf mois ; la hausse du coût du risque (+9,1 % au premier semestre) pèse sur la rentabilité.","tableau":{"colonnes":["Période 2026","PNB (Md FCFA)","Variation","Résultat net (Md FCFA)","Variation","Source"],"lignes":[["1er trimestre (31 mars)","65,6","−1,1 %","24,0","−11,4 %","Base WESTBOURSE"],["1er semestre (30 juin)","134,1","+1,6 %","53,4","+0,6 %","Base WESTBOURSE ; bilan 4 054,5 Md (Sika Finance)"],["9 premiers mois (30 sept.)","197,6","−1,7 %","80,4","−3,5 %","Sika Finance, articles du 07/05/2026, 01/09/2026 et 02/11/2026 ; parts de marché : APBEF-CI, avril 2026"]],"note":"Comptes non audités. Variations calculées par rapport à la même période de 2025, en base. Les comptes intermédiaires sont des cumuls depuis le 1er janvier."},"donnees_reelles":{"vue":"cours","codes":["SGBC"],"actions":5}},{"type":"importance","titre":"La lecture de Société Générale Côte d’Ivoire","contenu":"Taille : la banque détient environ 18 % des crédits en Côte d’Ivoire (APBEF-CI, avril 2026, via Sika Finance). Croissance : solide jusqu’en 2023, puis quasi nulle pour le résultat 2025.\nRentabilité : ROE de 20,5 % sur les capitaux de clôture 2025 et 21,4 % sur les capitaux moyens, en baisse parce que les fonds propres ont été renforcés. La marge nette reste élevée, 36,7 % du PNB publié.\nQualité des actifs (2025, Sika Finance) : créances en souffrance autour de 8 % des crédits, couverture d’environ 82 %. Valorisation : le PER de fin d’année passe de 4,89 en 2021 à 9,18 en 2025, puis à 11,54 au cours du 23/11/2026.\nDividende : le montant publié pour 2025 (2 606 FCFA brut) dépasse de 59 % celui publié pour 2024 (1 639 FCFA, base fiscale non précisée) et représente 80 % du BPA 2025. Sa soutenabilité se vérifie dans les flux de trésorerie, pas dans le seul résultat.","simulation":{"type":"per","consigne":"Le PER de SGBC au 23/11/2026, sur le BPA 2025. Passez aux données réelles pour le recalculer au dernier cours.","cours":37610,"bpa":3257.73,"croissance_pct":0,"annees":3,"codes":["SGBC"]}},{"type":"retenir","titre":"L’essentiel","contenu":"Société Générale Côte d’Ivoire est une grande banque solide dont la croissance ralentit. Son ROE baisse parce que ses capitaux propres augmentent ; sa valorisation monte parce que le marché l’a réévaluée en 2026.","points":[{"titre":"Une série de PNB vérifiable","detail":"Les comptes intermédiaires départagent les séries annuelles."},{"titre":"ROE en baisse, fonds propres en hausse","detail":"Le dénominateur explique la baisse, pas le résultat."},{"titre":"Solvabilité confortable","detail":"17,6 % pour un minimum de 11,5 %."}]}],"quiz":[{"question":"Résultat net 2025 : 101,4 milliards ; capitaux propres de clôture : 495,1 milliards. Quel est le ROE de clôture ?","options":["21,4 %","20,5 %","22,4 %","36,7 %"],"correct":1,"explication":"101,4 ÷ 495,1 = 20,5 %. Sur les capitaux moyens, on trouve 21,4 %."},{"question":"Pourquoi le ROE de SGBC baisse-t-il en 2025 alors que son résultat est stable ?","options":["Parce que le PNB a été divisé par deux","Parce que ses capitaux propres ont fortement augmenté","Parce que la banque a cessé de verser le moindre dividende","Parce que le nombre d’actions a été réduit"],"correct":1,"explication":"Les capitaux propres passent de 451,7 à 495,1 milliards : à résultat égal, le ROE baisse mécaniquement."},{"question":"Sur neuf mois 2025, le PNB de SGBC atteint 201,0 milliards. Quelle série annuelle 2025 cela rend-il plausible ?","options":["Environ 276,0 milliards","Environ 333,5 milliards","Environ 600 milliards","Aucune des deux"],"correct":0,"explication":"Trois trimestres à 201,0 milliards donnent un rythme annuel proche de 276,0 ; atteindre 333,5 supposerait un dernier trimestre exceptionnel."},{"question":"Le ratio de solvabilité de SGBC est de 17,6 %. Que signifie-t-il ?","options":["Que la banque est insolvable","Que ses fonds propres couvrent largement le minimum réglementaire","Que 17,6 % de ses crédits à la clientèle sont aujourd’hui en souffrance","Que son coefficient d’exploitation est de 17,6 %"],"correct":1,"explication":"Fonds propres ÷ actifs pondérés : 17,6 % contre un minimum de 11,5 % dans l’UMOA."},{"question":"Dividende brut 2025 : 2 606 FCFA ; cours au 23/11/2026 : 37 610 FCFA. Quel est le rendement brut ?","options":["6,10 %","8,72 %","9,70 %","6,93 %"],"correct":3,"explication":"2 606 ÷ 37 610 = 6,93 % ; net, 6,10 %."}],"qcm":{"question":"Résultat net 2025 : 101,4 milliards ; capitaux propres de clôture : 495,1 milliards. Quel est le ROE de clôture ?","options":["21,4 %","20,5 %","22,4 %","36,7 %"],"correct":1,"explication":"101,4 ÷ 495,1 = 20,5 %. Sur les capitaux moyens, on trouve 21,4 %."},"liens":[{"label":"Les fiches sociétés","href":"/societes"},{"label":"Les dividendes","href":"/dividendes"},{"label":"Le calendrier","href":"/calendrier"}],"avertissement":"Ceci n’est pas un conseil en investissement. Les ratios décrivent le passé et ne garantissent aucune performance future. Investir en actions comporte un risque de perte en capital."},{"titre":"Leçon 0.6 — Comparer deux banques : ECOC face à SGBC","module":"Module 0 — Le cours complet : analyse fondamentale appliquée à la BRVM","categorie":"fundamental","duree_min":16,"sous_titre":"Même pays, même métier, deux profils : la plus rentable face à la plus grande, et ce qu’une comparaison honnête exige d’aligner.","resume":"Ecobank Côte d’Ivoire et Société Générale Côte d’Ivoire exercent le même métier sur le même marché. La première est plus rentable, la seconde plus grande et moins chère au regard du bénéfice. Cette leçon met les deux banques côte à côte, chiffre par chiffre et graphique par graphique, puis rappelle ce qu’il faut aligner avant de conclure.","nouveaute":{"type":"nouveau","depuis":"2026-11-24"},"sections":[{"type":"cas","titre":"Face à face au 23 novembre 2026","reel":true,"contenu":"Au 23 novembre 2026, Ecobank Côte d’Ivoire cotait 14 455 FCFA pour 795,8 milliards de capitalisation, Société Générale Côte d’Ivoire 37 610 FCFA pour 1 170,1 milliards. Le bloc en direct compare leurs ratios sur les derniers chiffres disponibles.\nLes deux banques partagent le même marché, la même monnaie et le même régulateur, la Commission bancaire de l’UMOA. Les écarts qui suivent tiennent donc à leur modèle : taille du bilan, part des dépôts prêtée, niveau de fonds propres, coût du risque. C’est ce qui rend la comparaison instructive, et c’est aussi ce qui en fixe les limites.","stats":[{"label":"Ecobank CI : cours","valeur":"14 455 FCFA","detail":"capitalisation 795,8 Md"},{"label":"Société Générale CI : cours","valeur":"37 610 FCFA","detail":"capitalisation 1 170,1 Md"},{"label":"Ecobank CI : ROE 2025","valeur":"29,0 %","detail":"capitaux de clôture"},{"label":"Société Générale CI : ROE 2025","valeur":"20,5 %","detail":"capitaux de clôture"}],"donnees_reelles":{"vue":"ratios","codes":["ECOC","SGBC"]}},{"type":"cas","titre":"Tableau de synthèse","reel":true,"contenu":"Chaque ligne compare la même grandeur, calculée de la même façon pour les deux banques. Les montants viennent des comptes 2025 publiés ; les cours, des clôtures du 23 novembre 2026. Le bloc en direct, sous le tableau, affiche le dernier dividende et le rendement au dernier cours.\nLa colonne « Écart » se lit selon la grandeur : un rapport (« 2,1× ») pour les tailles, une variation en pourcentage pour les montants, un écart en points pour les ratios déjà exprimés en pourcentage. Un écart de 8,6 points de ROE n’est pas une différence de 8,6 % : c’est la distance entre deux pourcentages.","tableau":{"colonnes":["Indicateur","ECOC","SGBC","Écart"],"lignes":[["PNB 2025 (Md FCFA)","132,7","276,0","SGBC 2,1×"],["Résultat net 2025 (Md FCFA)","63,5","101,4","SGBC +59,7 %"],["Total du bilan (Md FCFA)","2 054,5","3 769,2","SGBC 1,8×"],["Capitaux propres (Md FCFA)","218,6","495,1","SGBC 2,3×"],["Dépôts de la clientèle (Md FCFA)","1 626,2","2 907,7","SGBC +78,8 %"],["Crédits ÷ dépôts","64,6 %","87,6 %","SGBC prête une plus grande part de ses dépôts"],["ROE (capitaux de clôture)","29,0 %","20,5 %","ECOC +8,6 pts"],["ROE (capitaux moyens)","30,4 %","21,4 %","ECOC +9,0 pts"],["Marge nette (résultat ÷ PNB)","47,9 %","36,7 %","ECOC +11,1 pts"],["PER à la clôture 2025","13,87","9,18","SGBC moins chère"],["PER au 23/11/2026 (BPA 2025)","12,54","11,54","SGBC moins chère"],["PER sur 12 mois glissants (StockAnalysis)","14,04","12,26","SGBC moins chère"],["Dividende 2025 (FCFA)","888 brut / 781,44 net","2 606 brut / 2 293,28 net","SGBC 2,9×"],["Rendement brut au 23/11/2026","6,14 %","6,93 %","SGBC +0,79 pt"],["Performance depuis le 1er janvier 2026","−9,66 %","+25,81 %","SGBC nettement devant"],["Bêta sur un an (StockAnalysis)","0,64","0,68","Sensibilité au marché comparable"]],"note":"Sources : états financiers publiés (base WESTBOURSE) et clôtures de la BRVM, exercices 2021 à 2025, lus le 24/11/2026 ; calculs WESTBOURSE."},"donnees_reelles":{"vue":"rendement","codes":["ECOC","SGBC"]}},{"type":"cas","titre":"Les trajectoires côte à côte","reel":true,"contenu":"Les cinq graphiques suivants reprennent 2021-2025 pour les deux banques. Cliquez sur la légende pour masquer une série et isoler l’autre. Le dernier ramène les deux résultats à 100 en 2021 : il compare les trajectoires, pas les tailles.","graphiques":[{"type":"bar","titre":"PNB comparé (Md FCFA)","labels":["2021","2022","2023","2024","2025"],"unite":"Md FCFA","note":"PNB des comptes publiés. Sources : états financiers publiés (base WESTBOURSE) et clôtures de la BRVM, exercices 2021 à 2025, lus le 24/11/2026 ; calculs WESTBOURSE.","reel":true,"series":[{"nom":"ECOC","valeurs":[90.5,99.2,110.2,122.3,132.7]},{"nom":"SGBC","valeurs":[189.1,215.1,253.3,263.2,276]}]},{"type":"bar","titre":"Résultat net comparé (Md FCFA)","labels":["2021","2022","2023","2024","2025"],"unite":"Md FCFA","note":"Le résultat de SGBC plafonne depuis 2023 ; celui d’ECOC continue de croître jusqu’en 2025. Sources : états financiers publiés (base WESTBOURSE) et clôtures de la BRVM, exercices 2021 à 2025, lus le 24/11/2026 ; calculs WESTBOURSE.","reel":true,"series":[{"nom":"ECOC","valeurs":[34.3,44.6,48.1,57.5,63.5]},{"nom":"SGBC","valeurs":[67.4,74.6,97.2,101.2,101.4]}]},{"type":"line","titre":"PER à la clôture de chaque année","labels":["2021","2022","2023","2024","2025"],"unite":"x","note":"Cours de clôture de l’année ÷ BPA de l’exercice. Sources : états financiers publiés (base WESTBOURSE) et clôtures de la BRVM, exercices 2021 à 2025, lus le 24/11/2026 ; calculs WESTBOURSE.","reel":true,"series":[{"nom":"ECOC","valeurs":[7.68,6.1,7.79,8.42,13.87]},{"nom":"SGBC","valeurs":[4.89,4.84,5.14,6.45,9.18]}]},{"type":"line","titre":"Rendement du dividende à la clôture de chaque année (%)","labels":["2021","2022","2023","2024","2025"],"unite":"%","note":"Dividende de l’exercice tel que publié ÷ dernier cours de l’année : le rendement baisse quand le cours monte plus vite que le dividende. Sources : états financiers publiés (base WESTBOURSE) et clôtures de la BRVM, exercices 2021 à 2025, lus le 24/11/2026 ; calculs WESTBOURSE.","reel":true,"series":[{"nom":"ECOC","valeurs":[8.78,11.1,8.74,8.05,5.55]},{"nom":"SGBC","valeurs":[9.48,9.54,9.64,7.8,8.72]}]},{"type":"line","titre":"Résultat net, base 100 en 2021","labels":["2021","2022","2023","2024","2025"],"unite":"","note":"ECOC atteint 185 en 2025, SGBC 150. Sources : états financiers publiés (base WESTBOURSE) et clôtures de la BRVM, exercices 2021 à 2025, lus le 24/11/2026 ; calculs WESTBOURSE.","reel":true,"series":[{"nom":"ECOC","valeurs":[100,130.03,140.23,167.64,185.13]},{"nom":"SGBC","valeurs":[100,110.68,144.21,150.15,150.45]}]}],"donnees_reelles":{"vue":"historique","codes":["ECOC","SGBC"]}},{"type":"importance","titre":"Lecture comparée","contenu":"Six angles, six constats. Aucun ne suffit à départager les deux banques : c’est leur combinaison, avec des définitions alignées, qui fait l’analyse.\nD’où vient l’écart de rentabilité ? Le ROE se décompose : ROE = ROA × levier, le levier rapportant le bilan moyen aux capitaux propres moyens. ECOC obtient un ROA de 3,09 % avec un levier de 9,8, soit un ROE de 30,4 %. SGBC obtient 2,75 % avec un levier de 7,8, soit 21,4 %.\nL’écart vient donc des deux côtés : ECOC tire un peu plus de résultat de chaque franc de bilan, et elle le fait avec moins de fonds propres par franc engagé. Un levier plus élevé augmente le ROE quand tout va bien, et réduit le coussin quand les crédits se dégradent : c’est la contrepartie à garder en tête.","formules":[{"nom":"Décomposition du ROE","expression":"ROE = (résultat net ÷ bilan moyen) × (bilan moyen ÷ capitaux propres moyens) = ROA × levier","exemple":"ECOC 2025 : 3,09 % × 9,82 = 30,4 % ; SGBC : 2,75 % × 7,80 = 21,4 %"}],"points":[{"titre":"Taille","detail":"SGBC est nettement plus grande : PNB 2,1× plus élevé, bilan 1,8×, capitaux propres 2,3×. Elle détient environ 18 % des crédits en Côte d’Ivoire (APBEF-CI, avril 2026)."},{"titre":"Rentabilité","detail":"ECOC affiche un ROE plus élevé (29,0 % contre 20,5 % sur les capitaux de clôture, 30,4 % contre 21,4 % sur les capitaux moyens) et une marge nette supérieure (47,9 % contre 36,7 %)."},{"titre":"Valorisation","detail":"SGBC est moins chère au regard du bénéfice : PER 11,54 contre 12,54 au 23/11/2026. Cela peut refléter une croissance plus faible : son PNB recule de 1,7 % sur neuf mois 2026."},{"titre":"Dividende","detail":"SGBC distribue davantage par action (2 293,28 FCFA net contre 781,44) et offre un rendement brut plus élevé au cours du 23/11/2026 (6,93 % contre 6,14 %)."},{"titre":"Qualité des actifs","detail":"ECOC : coût du risque de 0,2 % en 2025, couverture d’environ 90 % à mi-2026. SGBC : créances en souffrance autour de 8 %, couverture d’environ 82 % en 2025. Ces indicateurs ne sont pas les mêmes : il faut retrouver le même dans chaque rapport.","verifier":"Coût du risque et taux de créances en souffrance ne mesurent pas la même chose."},{"titre":"Tendance boursière 2026","detail":"SGBC gagne 25,8 % depuis le 1er janvier, ECOC perd 9,7 %. Les comptes ne disent pas pourquoi ; on peut seulement constater que SGBC a renforcé ses fonds propres et relevé son dividende, et que le cours d’ECOC avait gagné 81,9 % en 2025."}],"simulation":{"type":"pb_roe","consigne":"P/B = PER × ROE : les deux banques au 23/11/2026, sur les comptes 2025. Passez aux données réelles pour les recalculer.","societes":[{"nom":"Ecobank CI (ECOC)","per":12.5,"roe_pct":29},{"nom":"Société Générale CI (SGBC)","per":11.5,"roe_pct":20.5}],"codes":["ECOC","SGBC"]}},{"type":"piege","titre":"Avertissement de comparabilité","contenu":"Le ROE de clôture et le ROE moyen ne se comparent qu’entre eux. Les deux banques peuvent présenter leurs comptes selon des référentiels différents, SYSCOHADA pour les comptes sociaux, IFRS pour certains comptes consolidés. Et les indicateurs de risque publiés ne sont pas homogènes d’une banque à l’autre.","encadres":[{"ton":"alerte","titre":"Ces chiffres illustrent la méthode","texte":"Ils ne suffisent pas à établir un classement définitif. Pour une comparaison complète, il faut aligner les normes comptables, la définition du résultat, la méthode du ROE, l’indicateur de qualité des crédits, le coût du risque, le dividende et sa base fiscale, le BPA, la date du cours et la liquidité du titre."}]},{"type":"retenir","titre":"Synthèse : ECOC face à SGBC","contenu":"SGBC est plus grande en PNB, en bilan et en capitaux propres. Elle présente un PER plus bas et un rendement du dividende plus élevé, et son cours a progressé en 2026 (+25,8 % depuis le 1er janvier).\nECOC affiche un ROE plus élevé et une meilleure marge nette : elle transforme mieux son PNB en résultat. Son résultat recule en 2026 sous l’effet d’un provisionnement prudent, et son cours recule aussi (−9,7 % depuis le 1er janvier).\nIl serait incorrect de désigner une banque « meilleure » sur cette seule base. Cette comparaison est informative et ne constitue pas une recommandation d’achat ou de vente."}],"quiz":[{"question":"Laquelle des deux banques transforme le mieux son PNB en résultat net en 2025 ?","options":["Société Générale CI","Les deux à égalité","Ecobank CI","Impossible à dire sans le cours"],"correct":2,"explication":"Marge nette 2025 : 47,9 % pour ECOC contre 36,7 % pour SGBC."},{"question":"Le résultat net d’ECOC vaut 185 en 2025, base 100 en 2021. Que mesure ce chiffre ?","options":["Le rendement du dividende versé chaque année depuis 2021","Une progression de 85 % du résultat depuis 2021","Le PER de 2025","La part de marché de la banque"],"correct":1,"explication":"Base 100 : 63,5 ÷ 34,3 × 100 = 185, soit +85 %."},{"question":"Pourquoi un PER plus bas ne prouve-t-il pas que SGBC est la meilleure affaire ?","options":["Parce que le PER de SGBC est faux","Parce qu’il peut refléter une croissance attendue plus faible","Parce que le PER ne s’applique pas aux banques, seulement aux industriels","Parce que SGBC ne verse pas de dividende"],"correct":1,"explication":"Le marché paie moins une banque dont le PNB recule en 2026 : un PER bas peut traduire des perspectives plus faibles."},{"question":"Que faut-il aligner avant de comparer la qualité des crédits de deux banques ?","options":["Leur cours de bourse","Leur nombre d’agences et de distributeurs automatiques","Le même indicateur, défini de la même façon","Leur date de création"],"correct":2,"explication":"Un coût du risque et un taux de créances en souffrance ne mesurent pas la même chose : il faut le même indicateur dans chaque rapport."},{"question":"P/B = PER × ROE. Avec un PER de 12,5 et un ROE de 29 %, quel est le P/B ?","options":["3,6","2,3","4,3","0,4"],"correct":0,"explication":"12,5 × 0,29 = 3,6 : le cours vaut 3,6 fois les capitaux propres par action."}],"qcm":{"question":"Laquelle des deux banques transforme le mieux son PNB en résultat net en 2025 ?","options":["Société Générale CI","Les deux à égalité","Ecobank CI","Impossible à dire sans le cours"],"correct":2,"explication":"Marge nette 2025 : 47,9 % pour ECOC contre 36,7 % pour SGBC."},"liens":[{"label":"Comparer des actions","href":"/actions/compare"},{"label":"La valorisation de toutes les valeurs","href":"/premium/valorisation"},{"label":"Les secteurs","href":"/secteurs"}],"avertissement":"Ceci n’est pas un conseil en investissement. Les ratios décrivent le passé et ne garantissent aucune performance future. Investir en actions comporte un risque de perte en capital."},{"titre":"Leçon 0.7 — Télécoms : Sonatel face à Orange Côte d’Ivoire","module":"Module 0 — Le cours complet : analyse fondamentale appliquée à la BRVM","categorie":"fundamental","duree_min":22,"sous_titre":"La même grille appliquée à deux opérateurs : un groupe multi-pays de très grande taille face à un groupe régional en croissance rapide.","resume":"Après les banques, la même grille d’analyse s’applique à deux opérateurs de télécommunications. Contrairement aux banques, les télécoms se lisent avec les ratios classiques d’endettement, d’EV/EBITDA et de free cash flow. Sonatel est plus grande, plus rentable et plus liquide ; Orange Côte d’Ivoire croît plus vite et se paie plus cher. Cette leçon le montre chiffres à l’appui, et explique pourquoi trois PER différents circulent pour chacune.","nouveaute":{"type":"nouveau","depuis":"2026-11-24"},"sections":[{"type":"definition","titre":"Ce qui change pour un opérateur télécom","contenu":"Un opérateur de télécommunications est une entreprise industrielle : il investit lourdement dans ses réseaux (les capex), puis vend des abonnements, des données mobiles et des services financiers comme le mobile money. Sa dette sert à financer ces investissements.\nLes ratios écartés pour les banques reprennent donc tout leur sens : dette nette, gearing, EV/EBITDA, free cash flow. Il faut aussi savoir lire un groupe : Sonatel et Orange Côte d’Ivoire consolident des filiales dans plusieurs pays, dont elles ne détiennent pas 100 %. Le résultat consolidé inclut la part des actionnaires minoritaires ; le résultat part du groupe ne la compte pas."},{"type":"cas","titre":"Les deux profils","reel":true,"contenu":"Au 23 novembre 2026, Sonatel cotait 3 900 FCFA pour 3 900 milliards de capitalisation (un milliard d’actions depuis le fractionnement), Orange Côte d’Ivoire 19 005 FCFA pour 2 863,2 milliards : Sonatel pèse 36 % de plus en bourse.","points":[{"titre":"Sonatel (SNTS)","detail":"Premier opérateur du Sénégal, présent dans cinq pays (Sénégal, Mali, Guinée-Bissau, Guinée, Sierra Leone). Filiale du groupe Orange, sous la marque Orange. Fondée en 1985, cotée à la BRVM depuis 1998. Action fractionnée le 26/10/2026 : une action ancienne en a donné dix, ce qui a ramené le cours d’environ 40 000 à environ 4 000 FCFA."},{"titre":"Orange Côte d’Ivoire (ORAC)","detail":"Opérateur leader en Côte d’Ivoire, présent aussi au Burkina Faso et au Liberia. Filiale du groupe Orange, cotée à la BRVM depuis fin 2022 (première séance en base le 30/12/2022). Mobile, fixe, internet, fibre et Orange Money ; 40,35 millions de lignes à fin septembre 2026 (Sika Finance)."}],"stats":[{"label":"Sonatel : cours au 23/11/2026","valeur":"3 900 FCFA","detail":"capitalisation 3 900 Md"},{"label":"Orange CI : cours au 23/11/2026","valeur":"19 005 FCFA","detail":"capitalisation 2 863,2 Md"}],"donnees_reelles":{"vue":"cours","codes":["SNTS","ORAC"],"actions":10}},{"type":"cas","titre":"Sonatel : les comptes 2021-2025","reel":true,"contenu":"Le chiffre d’affaires passe de 1 334,9 à 1 923,1 milliards de FCFA (9,6 % par an), le résultat net consolidé de 252,5 à 413,6 milliards (13,1 % par an). La part du groupe, selon S&P Global, est plus faible : 342,0 milliards en 2025, les 71,6 milliards d’écart revenant aux actionnaires minoritaires des filiales.\nD’où deux marges nettes et deux PER pour la même année. Aucun n’est faux ; ils ne répondent pas à la même question. Le PER sur le résultat part du groupe mesure ce que l’actionnaire de Sonatel paie pour la part qui lui revient.","tableau":{"colonnes":["Indicateur","2021","2022","2023","2024","2025"],"lignes":[["Chiffre d’affaires (Md FCFA)","1 334,9","1 455,0","1 620,7","1 776,4","1 923,1"],["Croissance du chiffre d’affaires","—","+9,0 %","+11,4 %","+9,6 %","+8,3 %"],["Résultat net consolidé (Md FCFA)","252,5","278,9","331,7","393,7","413,6"],["Croissance du résultat net consolidé","—","+10,5 %","+18,9 %","+18,7 %","+5,1 %"],["Résultat net part du groupe, S&P (Md FCFA)","211,1","236,0","279,4","328,8","342,0"],["BPA consolidé (FCFA)","252,46","278,90","331,70","393,70","413,60"],["EBITDA estimé, S&P (Md FCFA)","400","435","520","618","681"],["Marge brute, S&P","57,0 %","56,1 %","58,0 %","58,9 %","60,7 %"],["Marge opérationnelle, S&P","30,0 %","30,0 %","32,1 %","34,8 %","35,4 %"],["Marge nette consolidée","18,9 %","19,2 %","20,5 %","22,2 %","21,5 %"],["Marge nette part du groupe","15,8 %","16,2 %","17,2 %","18,5 %","17,8 %"],["Capitaux propres (Md FCFA)","821,3","898,5","1 065,7","1 274,6","1 399,3"],["ROE consolidé (capitaux de clôture)","30,7 %","31,0 %","31,1 %","30,9 %","29,6 %"],["Free cash flow, S&P (Md FCFA)","242","201","355","359","364"],["Dette nette, S&P (Md FCFA)","−199","−146","14","−3","133"],["Investissements (capex), S&P (Md FCFA)","221","263","288","301","318"],["Cours de clôture de l’année (FCFA)","1 397,5","1 520","1 798","2 400","2 612"],["PER à la clôture (BPA consolidé)","5,54","5,45","5,42","6,10","6,32"],["PER à la clôture (part du groupe, S&P)","6,62","6,44","6,43","7,30","7,64"],["Dividende par action publié (FCFA)","140,00","150,00","157,50","165,50","174,00"],["Rendement à la clôture de l’année","10,0 %","9,9 %","8,8 %","6,9 %","6,7 %"]],"note":"Lignes « S&P » : StockAnalysis / S&P Global Market Intelligence, consulté le 23/11/2026. Autres lignes : comptes publiés en base WESTBOURSE et clôtures de la BRVM, cours et BPA ajustés du fractionnement par 10 du 26/10/2026. « — » : donnée absente de la source."},"donnees_reelles":{"vue":"historique","codes":["SNTS"]}},{"type":"cas","titre":"Orange Côte d’Ivoire : les comptes 2021-2025","reel":true,"contenu":"Le chiffre d’affaires stagne en 2022 puis accélère : +10,4 % en 2025, à 1 197,1 milliards. Le résultat net consolidé progresse de 6,1 % en 2025, à 167,8 milliards ; la part du groupe, selon S&P Global, atteint 129,1 milliards.\nLes capitaux propres en base restent stables, entre 708 et 727 milliards sur la période : c’est sur eux que se calcule le ROE consolidé de 23,7 % en 2025. La dette nette, selon S&P Global, s’établit à 149 milliards en 2025, contre 46 milliards en 2022.","tableau":{"colonnes":["Indicateur","2021","2022","2023","2024","2025"],"lignes":[["Chiffre d’affaires (Md FCFA)","965,0","965,0","1 016,5","1 084,1","1 197,1"],["Croissance du chiffre d’affaires","—","0,0 %","+5,3 %","+6,7 %","+10,4 %"],["Résultat net consolidé (Md FCFA)","155,8","153,5","154,9","158,2","167,8"],["Croissance du résultat net consolidé","—","−1,5 %","+0,9 %","+2,1 %","+6,1 %"],["Résultat net part du groupe, S&P (Md FCFA)","125,4","118,3","110,5","112,8","129,1"],["BPA consolidé (FCFA)","1 034,38","1 018,78","1 028,00","1 050,00","1 114,00"],["EBITDAaL estimé, S&P (Md FCFA)","256","255","251","266","288"],["Marge brute, S&P","57,5 %","55,5 %","61,7 %","54,1 %","53,3 %"],["Marge opérationnelle, S&P","26,6 %","26,5 %","24,7 %","24,6 %","24,0 %"],["Marge nette consolidée","16,1 %","15,9 %","15,2 %","14,6 %","14,0 %"],["Marge nette part du groupe","13,0 %","12,3 %","10,9 %","10,4 %","10,8 %"],["Capitaux propres (Md FCFA)","727,1","725,5","724,0","713,8","707,8"],["ROE consolidé (capitaux de clôture)","21,4 %","21,2 %","21,4 %","22,2 %","23,7 %"],["Free cash flow, S&P (Md FCFA)","149","125","88","97","151"],["Dette nette, S&P (Md FCFA)","—","46","175","134","149"],["Investissements (capex), S&P (Md FCFA)","159","172","194","160","184"],["Cours de clôture de l’année (FCFA)","—","10 210","10 900","17 500","14 250"],["PER à la clôture (BPA consolidé)","—","10,02","10,60","16,67","12,79"],["PER à la clôture (part du groupe, S&P)","—","—","14,87","23,37","16,63"],["Dividende par action publié (FCFA)","717,00","752,76","780,00","660,00","800,00"],["Rendement à la clôture de l’année","—","7,4 %","7,2 %","3,8 %","5,6 %"]],"note":"Lignes « S&P » : StockAnalysis / S&P Global Market Intelligence, consulté le 23/11/2026. Autres lignes : comptes publiés en base WESTBOURSE et clôtures de la BRVM ; pas de clôture pour 2021, le titre n’étant coté qu’à partir de fin 2022. « — » : donnée absente de la source."},"donnees_reelles":{"vue":"historique","codes":["ORAC"]}},{"type":"cas","titre":"Trajectoires comparées et comptes de 2026","reel":true,"contenu":"Sur neuf mois 2026, Sonatel affiche 1 583,0 milliards de chiffre d’affaires (+10,5 %) et 354,0 milliards de résultat net consolidé (+13,8 %). Orange Côte d’Ivoire, 1 012,0 milliards (+15,6 %) et 141,0 milliards (+18,7 %).\nSelon Sika Finance, l’EBITDAaL d’Orange Côte d’Ivoire progresse d’environ 18 % sur neuf mois 2026 et ses investissements hors licences (eCapex) d’environ 20 %. Le bloc en direct, sous les graphiques, donne le dernier dividende et le rendement au dernier cours.","tableau":{"colonnes":["Période 2026","Société","Chiffre d’affaires (Md FCFA)","Variation","Résultat net (Md FCFA)","Variation"],"lignes":[["1er trimestre","Sonatel","504,2","+6,9 %","113,8","+5,0 %"],["1er semestre","Sonatel","1 049,8","+9,3 %","230,0","+10,5 %"],["9 premiers mois","Sonatel","1 583,0","+10,5 %","354,0","+13,8 %"],["1er trimestre","Orange CI","325,6","+14,8 %","48,3","+25,1 %"],["9 premiers mois","Orange CI","1 012,0","+15,6 %","141,0","+18,7 %"]],"note":"Comptes consolidés, non audités, en base WESTBOURSE ; variations par rapport à la même période de 2025. Les comptes intermédiaires sont des cumuls depuis le 1er janvier ; le semestre d’Orange CI n’est pas en base."},"graphiques":[{"type":"bar","titre":"Chiffre d’affaires comparé (Md FCFA, 2021-2025)","labels":["2021","2022","2023","2024","2025"],"unite":"Md FCFA","note":"Sonatel réalise 1,6 fois le chiffre d’affaires d’Orange CI en 2025. Sources : états financiers publiés (base WESTBOURSE) et clôtures de la BRVM, exercices 2021 à 2025, lus le 24/11/2026 ; calculs WESTBOURSE.","reel":true,"series":[{"nom":"Sonatel","valeurs":[1334.9,1455,1620.7,1776.4,1923.1]},{"nom":"Orange CI","valeurs":[965,965,1016.5,1084.1,1197.1]}]},{"type":"bar","titre":"Résultat net consolidé comparé (Md FCFA, 2021-2025)","labels":["2021","2022","2023","2024","2025"],"unite":"Md FCFA","note":"Résultat consolidé, minoritaires compris ; en part du groupe (S&P Global), Sonatel 342,0 et Orange CI 129,1 milliards en 2025. Sources : états financiers publiés (base WESTBOURSE) et clôtures de la BRVM, exercices 2021 à 2025, lus le 24/11/2026 ; calculs WESTBOURSE.","reel":true,"series":[{"nom":"Sonatel","valeurs":[252.5,278.9,331.7,393.7,413.6]},{"nom":"Orange CI","valeurs":[155.8,153.5,154.9,158.2,167.8]}]},{"type":"line","titre":"PER à la clôture de chaque année (BPA consolidé)","labels":["2021","2022","2023","2024","2025"],"unite":"x","note":"Pas de point pour Orange CI en 2021 : le titre n’était pas encore coté. Sur la part du groupe, les PER sont plus élevés (S&P Global). Sources : états financiers publiés (base WESTBOURSE) et clôtures de la BRVM, exercices 2021 à 2025, lus le 24/11/2026 ; calculs WESTBOURSE.","reel":true,"series":[{"nom":"Sonatel","valeurs":[5.54,5.45,5.42,6.1,6.32]},{"nom":"Orange CI","valeurs":[null,10.02,10.6,16.67,12.79]}]},{"type":"line","titre":"Rendement du dividende à la clôture de chaque année (%)","labels":["2021","2022","2023","2024","2025"],"unite":"%","note":"Dividende de l’exercice tel que publié ÷ dernier cours de l’année. Sources : états financiers publiés (base WESTBOURSE) et clôtures de la BRVM, exercices 2021 à 2025, lus le 24/11/2026 ; calculs WESTBOURSE.","reel":true,"series":[{"nom":"Sonatel","valeurs":[10.02,9.87,8.76,6.9,6.66]},{"nom":"Orange CI","valeurs":[null,7.37,7.16,3.77,5.61]}]}],"donnees_reelles":{"vue":"rendement","codes":["SNTS","ORAC"]}},{"type":"cas","titre":"Marché et liquidité au 23 novembre 2026","reel":true,"contenu":"Trois PER circulent pour chaque opérateur, et ils sont tous justes. Sur le BPA consolidé 2025 et le cours du 23/11/2026 : 9,43 pour Sonatel, 17,06 pour Orange CI. Le Bulletin officiel de la cote du 20/11/2026 donnait 9,77 et 17,28 : c’est le même calcul au cours du 20 novembre (4 040 et 19 250 FCFA).\nStockAnalysis affiche 11,25 et 20,27 : un bénéfice sur douze mois glissants, en part du groupe. Même chose pour le rendement : 4,46 % et 3,70 % sur le dividende net 2025 et le cours du jour, quand Sika Finance affiche 6,66 % et 4,02 %.\nPour Sonatel, le chiffre de Sika Finance se retrouve en rapportant le même dividende net à la clôture 2025 : 174 ÷ 2 612 = 6,66 %. Même dividende, autre cours. Une analyse sérieuse dit toujours lequel elle utilise.","tableau":{"colonnes":["Indicateur","Sonatel (SNTS)","Orange CI (ORAC)","Écart"],"lignes":[["Cours au 23/11/2026","3 900 FCFA","19 005 FCFA","—"],["Capitalisation","3 900 Md FCFA","2 863,2 Md FCFA","SNTS +36 %"],["PER (BPA consolidé 2025, cours du 23/11)","9,43","17,06","SNTS moins chère"],["PER du Bulletin officiel (20/11/2026)","9,77","17,28","Même calcul au cours du 20/11"],["PER sur 12 mois glissants (StockAnalysis)","11,25","20,27","Part du groupe"],["Dividende 2025 (FCFA)","174 net","800 brut / 704 net","—"],["Rendement net au 23/11/2026","4,46 %","3,70 %","SNTS +0,76 pt"],["Rendement affiché par Sika Finance","6,66 %","4,02 %","Définition propre à Sika"],["ROE consolidé 2025 (capitaux de clôture)","29,6 %","23,7 %","SNTS +5,9 pts"],["Marge nette consolidée 2025","21,5 %","14,0 %","SNTS +7,5 pts"],["Taux de distribution 2025 (dividende net ÷ BPA)","42,1 %","63,2 %","ORAC distribue une plus grande part"],["Bêta sur un an (StockAnalysis)","1,37","1,35","Sensibilité au marché comparable"],["Titres échangés le 23/11/2026","88 961","2 509","SNTS bien plus liquide"],["Performance depuis le 1er janvier 2026","+49,31 %","+33,37 %","SNTS devant"],["Performance sur un an (depuis le 24/11/2025)","+55,1 %","+30,6 %","SNTS devant"],["Performance sur trois ans (depuis le 23/11/2023)","+125,5 %","+80,1 %","SNTS devant"]],"note":"Cours, volumes, BPA et dividendes : base WESTBOURSE (clôtures de la BRVM, comptes publiés, calendrier des dividendes). Performances calculées sur nos clôtures aux dates indiquées ; d’autres sites retiennent d’autres dates de référence."},"encadres":[{"ton":"info","titre":"Pourquoi les sources ne donnent pas le même PER","texte":"Trois raisons, toujours les mêmes : la date du cours retenu, le bénéfice utilisé (exercice clos ou douze mois glissants, consolidé ou part du groupe) et, pour le rendement, la définition du dividende (brut ou net, de l’exercice ou versé dans l’année). C’est pourquoi ce cours présente les sources côte à côte, chacune avec sa définition."}],"simulation":{"type":"distribution","consigne":"Sonatel 2025 : 413,6 milliards de résultat consolidé pour 1 milliard d’actions. Avec un taux de distribution de 42 %, retrouvez le dividende net par action.","resultat_net":413600000000,"actions":1000000000,"taux_distribution_pct":42.1},"donnees_reelles":{"vue":"ratios","codes":["SNTS","ORAC"]}},{"type":"importance","titre":"Lecture comparée des deux opérateurs","contenu":"Huit angles, huit constats. Comme pour les banques, ils ne désignent pas un gagnant : ils décrivent deux profils.","points":[{"titre":"Taille et présence","detail":"Sonatel réalise 1,6 fois le chiffre d’affaires d’Orange CI (1 923,1 contre 1 197,1 milliards en 2025), dans cinq pays contre trois. Sa capitalisation dépasse celle d’Orange CI de 36 %."},{"titre":"Rentabilité","detail":"Marge nette consolidée de 21,5 % contre 14,0 %, ROE de 29,6 % contre 23,7 %, marge opérationnelle de 35,4 % contre 24,0 % (S&P Global) : Sonatel garde plus de chaque franc de chiffre d’affaires."},{"titre":"Croissance","detail":"Orange CI croît plus vite : +10,4 % de chiffre d’affaires en 2025 contre +8,3 %, et +18,7 % de résultat sur neuf mois 2026 contre +13,8 %."},{"titre":"Valorisation","detail":"Sonatel se négocie à un PER de 9,43 à 11,25 selon la source, Orange CI de 17,06 à 20,27 : le marché paie plus cher chaque franc de bénéfice d’Orange CI."},{"titre":"Trésorerie et investissements","detail":"Capex 2025 : 318 milliards pour Sonatel (16,5 % du chiffre d’affaires), 184 pour Orange CI (15,4 %). Free cash flow : 364 et 151 milliards (S&P Global)."},{"titre":"Liquidité boursière","detail":"88 961 titres Sonatel échangés le 23/11/2026, contre 2 509 pour Orange CI. Le fractionnement d’octobre 2026 a aussi ramené le prix d’une action Sonatel à la portée d’un petit budget."},{"titre":"Dividende","detail":"Sonatel distribue 42 % de son BPA consolidé 2025 en dividende net, avec un dividende net en hausse de 5,6 % par an depuis 2021 ; Orange CI distribue 63 %, mais son rendement au cours du jour est plus faible après la hausse du titre."},{"titre":"Tendance boursière 2026","detail":"Les deux titres progressent : +49,3 % pour Sonatel et +33,4 % pour Orange CI depuis le 1er janvier, dans une année où les deux résultats augmentent."}]},{"type":"piege","titre":"Avertissement de comparabilité","contenu":"Les PER et les rendements diffèrent selon les sources parce que les définitions et les dates varient. Mélanger un PER consolidé et un PER part du groupe, ou un rendement brut et un rendement net, fausse toute comparaison.","encadres":[{"ton":"alerte","titre":"Toujours indiquer la source et la méthode","texte":"WESTBOURSE calcule ses ratios sur les comptes de l’exercice clos et le dernier cours ; StockAnalysis utilise douze mois glissants et la part du groupe ; Sika Finance affiche un rendement selon sa propre définition du dividende et du cours. Dans toute publication, écrivez lequel vous retenez."}]},{"type":"retenir","titre":"Synthèse : Sonatel face à Orange Côte d’Ivoire","contenu":"Sonatel est plus grande, plus rentable, moins chère au regard du bénéfice et bien plus liquide ; son rendement du dividende est plus élevé. Elle présente un profil de rendement et de stabilité à grande échelle.\nOrange Côte d’Ivoire croît plus vite, sur trois marchés, et le marché lui accorde un PER plus élevé : elle présente un profil de croissance, payé plus cher.\nLe choix entre les deux profils dépend de l’objectif de chacun. Cette comparaison est informative et ne constitue pas une recommandation d’achat ou de vente."}],"quiz":[{"question":"Le résultat consolidé 2025 de Sonatel est de 413,6 milliards, la part du groupe de 342,0. À qui revient la différence ?","options":["À l’État du Sénégal","Aux actionnaires minoritaires des filiales","Aux banques qui ont financé les investissements du groupe","Au fisc"],"correct":1,"explication":"Le résultat consolidé inclut la part des actionnaires minoritaires des filiales que Sonatel ne détient pas à 100 % ; la part du groupe l’exclut."},{"question":"Au cours du 20/11/2026 (4 040 FCFA) et avec un BPA consolidé de 413,60 FCFA, quel PER obtient-on pour Sonatel ?","options":["9,43","11,25","9,77","6,32"],"correct":2,"explication":"4 040 ÷ 413,60 = 9,77, le chiffre du Bulletin officiel de la cote du 20/11/2026."},{"question":"Pourquoi StockAnalysis affiche-t-il un PER plus élevé pour Sonatel que celui calculé sur les comptes 2025 ?","options":["Parce qu’il utilise un cours plus ancien","Parce qu’il retient un autre bénéfice, en part du groupe et sur douze mois","Parce qu’il ignore le fractionnement d’octobre 2026 et garde l’ancien nombre d’actions","Parce qu’il ajoute le dividende au cours"],"correct":1,"explication":"Un bénéfice plus petit (part du groupe) au dénominateur donne un PER plus grand : la différence vient de la définition, pas d’une erreur."},{"question":"Quelle société croît le plus vite en 2025 et sur les neuf premiers mois de 2026 ?","options":["Sonatel","Les deux au même rythme","Aucune ne croît","Orange Côte d’Ivoire"],"correct":3,"explication":"Orange CI : +10,4 % de chiffre d’affaires en 2025 et +18,7 % de résultat sur neuf mois 2026."},{"question":"88 961 titres Sonatel échangés contre 2 509 titres Orange CI le même jour. Qu’en déduire ?","options":["Qu’Orange CI est plus chère","Qu’un ordre important s’exécute plus facilement sur Sonatel","Que Sonatel verse chaque année un dividende plus élevé que celui d’Orange Côte d’Ivoire","Que les deux titres sont aussi liquides"],"correct":1,"explication":"Un volume élevé signifie qu’un ordre trouve plus facilement une contrepartie sans déplacer le cours."}],"qcm":{"question":"Le résultat consolidé 2025 de Sonatel est de 413,6 milliards, la part du groupe de 342,0. À qui revient la différence ?","options":["À l’État du Sénégal","Aux actionnaires minoritaires des filiales","Aux banques qui ont financé les investissements du groupe","Au fisc"],"correct":1,"explication":"Le résultat consolidé inclut la part des actionnaires minoritaires des filiales que Sonatel ne détient pas à 100 % ; la part du groupe l’exclut."},"liens":[{"label":"Comparer des actions","href":"/actions/compare"},{"label":"La liquidité de chaque valeur","href":"/liquidite"},{"label":"Les dividendes","href":"/dividendes"}],"avertissement":"Ceci n’est pas un conseil en investissement. Les ratios décrivent le passé et ne garantissent aucune performance future. Investir en actions comporte un risque de perte en capital."},{"titre":"Leçon 0.8 — Méthode, signaux d’alerte et conclusion","module":"Module 0 — Le cours complet : analyse fondamentale appliquée à la BRVM","categorie":"fundamental","duree_min":16,"sous_titre":"La méthode en huit étapes, les huit signaux d’alerte, un tableau de suivi rempli, les erreurs courantes et un modèle de conclusion.","resume":"Cette dernière leçon du module rassemble l’outillage : la méthode pratique en huit étapes, les signaux d’alerte à reconnaître, un modèle de tableau de suivi rempli avec les comptes d’Ecobank Côte d’Ivoire, les erreurs les plus courantes et leur correction, les conclusions des deux comparaisons, un modèle de conclusion pour une fiche et la liste des sources consultées.","nouveaute":{"type":"nouveau","depuis":"2026-11-24"},"sections":[{"type":"definition","titre":"La méthode pratique en huit étapes","contenu":"Les huit étapes reprennent le parcours de la leçon 0.1 en le rendant opérationnel. Chacune produit quelque chose : un tableau, une note, une hypothèse écrite.\nL’ordre compte. Choisir les ratios avant d’avoir compris l’activité conduit à appliquer à une banque les indicateurs d’un industriel ; évaluer avant d’avoir vérifié la qualité des comptes revient à valoriser un bénéfice qui n’existe peut-être pas.","etapes":[{"titre":"Rassembler les données","detail":"Les états financiers sur au moins trois exercices ; la date et la source de chaque donnée."},{"titre":"Vérifier la qualité","detail":"Le rapport d’audit, les annexes, les changements de méthode et les opérations exceptionnelles."},{"titre":"Comprendre l’activité","detail":"Le modèle économique, les clients, les coûts, les concurrents et les risques principaux."},{"titre":"Observer les tendances","detail":"PNB ou chiffre d’affaires, marges, résultat net, BPA, dette, flux de trésorerie et dividendes sur plusieurs années."},{"titre":"Choisir les ratios adaptés","detail":"Ceux du secteur : pas les indicateurs d’une entreprise industrielle pour une banque.","cle":true},{"titre":"Évaluer la valorisation","detail":"Plusieurs méthodes (multiples, DCF, dividende) et plusieurs scénarios, pas un seul chiffre."},{"titre":"Tenir compte du marché","detail":"Liquidité, flottant, écart achat-vente et volumes : le prix affiché n’est pas forcément un prix d’exécution réaliste."},{"titre":"Conclure avec équilibre","detail":"Forces, faiblesses, risques, hypothèses de valorisation et ce qui pourrait changer l’analyse.","cle":true}]},{"type":"piege","titre":"Risques et signaux d’alerte","contenu":"Huit situations doivent faire ralentir l’analyse. Aucune n’est une condamnation ; chacune appelle une vérification dans les comptes.\nAppliqués aux sociétés de ce module, ces signaux orientent les vérifications sans rien trancher. Le dividende publié pour 2025 par Société Générale Côte d’Ivoire représente 80 % de son BPA : un taux élevé, qui reste sous le bénéfice mais appelle un regard sur les flux de trésorerie. Orange Côte d’Ivoire distribue 63 % de son BPA en dividende net, Sonatel 42 %.\nLa dette nette de Sonatel, selon S&P Global, passe de −3 milliards en 2024 à 133 milliards en 2025 ; elle reste modeste au regard de son free cash flow (364 milliards en 2025). Chez Ecobank Côte d’Ivoire, c’est le coût du risque qui se tend en 2026, après une année 2025 très favorable : le signal à suivre est la qualité des crédits, pas l’endettement.","points":[{"titre":"Bénéfices en hausse, trésorerie en baisse","detail":"Si les bénéfices progressent mais que les flux de trésorerie opérationnels se dégradent durablement, il faut chercher une hausse des créances, des stocks ou d’autres éléments."},{"titre":"Dette qui progresse plus vite que les résultats","detail":"Un endettement croissant sans croissance proportionnelle des résultats est un signal de risque."},{"titre":"Réserves du commissaire aux comptes","detail":"Des réserves d’audit ou des retards importants de publication doivent alerter sur la qualité de l’information."},{"titre":"Dividendes supérieurs aux bénéfices","detail":"Si les dividendes dépassent durablement les bénéfices et les flux de trésorerie, la distribution n’est pas soutenable."},{"titre":"Dépendance excessive","detail":"Une forte dépendance à un produit, un client, un fournisseur ou une matière première augmente le risque."},{"titre":"Résultat reposant sur l’exceptionnel","detail":"Un résultat gonflé par des éléments non récurrents (cession d’actifs, reprise de provisions) ne préjuge pas de la rentabilité future."},{"titre":"Faible flottant ou échanges rares","detail":"Un titre peu liquide est difficile à acheter ou à vendre sans effet sur le cours : le prix affiché peut être trompeur."},{"titre":"Dilution des actionnaires","detail":"Des augmentations de capital répétées diluent la part des actionnaires existants sans contrepartie claire."}]},{"type":"cas","titre":"Modèle de tableau de suivi, rempli avec Ecobank Côte d’Ivoire","reel":true,"contenu":"Le modèle tient sur une page : trois exercices, une tendance, une source datée par ligne. Reproduisez-le pour chaque société suivie ; le bloc en direct, en dessous, recalcule les ratios au dernier cours.\nLa colonne « Tendance » compare 2025 à 2023 : « en hausse » au-delà de +2 %, « en baisse » en deçà de −2 %, « stable » entre les deux. Sur Ecobank Côte d’Ivoire, presque tout monte : PNB, résultat, fonds propres, dividende. Mais le PER passe aussi de 7,79 à 13,87, et le rendement à la clôture recule de 8,7 % à 5,5 %. Le tableau dit à la fois que l’entreprise a progressé et que son cours a progressé plus vite qu’elle.","tableau":{"colonnes":["Indicateur","2023","2024","2025","Tendance","Source et date"],"lignes":[["PNB (Md FCFA)","110,2","122,3","132,7","En hausse","Comptes publiés, BRVM"],["Résultat net (Md FCFA)","48,1","57,5","63,5","En hausse","Comptes publiés, BRVM"],["ROE (capitaux de clôture)","27,0 %","28,8 %","29,0 %","En hausse","Calcul WESTBOURSE"],["Total du bilan (Md FCFA)","1 953,3","2 050,7","2 054,5","En hausse","Comptes publiés, BRVM"],["Capitaux propres (Md FCFA)","178,2","199,4","218,6","En hausse","Comptes publiés, BRVM"],["Dividende par action publié (FCFA)","594,00","708,00","888 brut","En hausse","Calendrier des dividendes, BRVM"],["PER à la clôture de l’année","7,79","8,42","13,87","En hausse","Calcul WESTBOURSE"],["Rendement à la clôture de l’année","8,7 %","8,1 %","5,5 %","En baisse","Calcul WESTBOURSE"],["Cours de clôture de l’année (FCFA)","6 800","8 795","16 000","En hausse","Clôtures de la BRVM"]],"note":"Une tendance « en hausse » du PER ou « en baisse » du rendement n’est ni bonne ni mauvaise en soi : elle dit que le cours a monté plus vite que le bénéfice ou le dividende."},"donnees_reelles":{"vue":"ratios","codes":["ECOC"]}},{"type":"piege","titre":"Erreurs courantes à éviter","contenu":"Neuf erreurs reviennent sans cesse, chez les débutants comme chez les lecteurs pressés. Chacune a sa correction.\nCe module en a croisé plusieurs sur des cas réels. Trois PER différents pour Sonatel au même moment (9,43, 9,77 et 11,25) illustrent l’erreur des périodes et des définitions mélangées. Deux séries de PNB pour Ecobank Côte d’Ivoire illustrent celle des données retraitées. Le rendement de 6,66 % affiché pour Sonatel, qui se retrouve exactement sur la clôture 2025 et non sur le cours du jour, illustre celle de la date du cours.","tableau":{"colonnes":["Erreur","Correction"],"lignes":[["Conclure qu’une action est bon marché parce que son cours est bas.","Un cours bas peut refléter des problèmes fondamentaux. Comparez avec une valeur estimée, pas avec un cours passé."],["Acheter sur la base d’un PER faible sans vérifier la qualité des bénéfices.","Vérifiez si le bénéfice est récurrent ou exceptionnel. Privilégiez un bénéfice normalisé."],["Confondre bénéfice comptable et trésorerie disponible.","Examinez le tableau des flux de trésorerie : le bénéfice peut être positif alors que la trésorerie se dégrade."],["Comparer directement des sociétés de secteurs différents.","Les ratios pertinents varient selon le secteur. Ne comparez pas une banque avec une entreprise industrielle."],["Utiliser un dividende passé comme s’il était garanti.","Le dividende futur n’est jamais garanti. Examinez les bénéfices et les flux de trésorerie pour juger sa soutenabilité."],["Calculer un ratio avec des données de périodes différentes.","Homogénéisez les périodes : le PER doit associer un cours et un bénéfice de la même période."],["Ignorer la liquidité du titre.","Vérifiez les volumes et l’écart achat-vente : un cours affiché peut ne pas être exécutable."],["Se fier à une seule année ou à un seul ratio.","Croisez plusieurs ratios sur plusieurs années et intégrez des éléments qualitatifs."],["Présenter une estimation comme une certitude.","Formulez des hypothèses explicites et présentez des scénarios. Toute valorisation est une approximation."]]}},{"type":"retenir","titre":"Les deux conclusions du module","contenu":"Les deux comparaisons se concluent de la même façon : elles décrivent des profils, elles ne désignent pas de gagnant.","encadres":[{"ton":"cle","titre":"Banques : ECOC face à SGBC (exercice 2025, cours au 23/11/2026)","texte":"SGBC est plus grande en PNB, en bilan et en capitaux propres ; elle présente un PER plus bas (11,54 contre 12,54) et un rendement du dividende plus élevé, et son cours a progressé en 2026 (+25,8 %).\nECOC affiche un ROE plus élevé (29,0 % contre 20,5 %) et une meilleure marge nette ; son résultat recule en 2026 sous l’effet d’un provisionnement prudent, et son cours recule aussi (−9,7 %).\nPour conclure davantage, il faudrait aligner normes comptables, définition du résultat, ROE sur capitaux moyens, indicateur de qualité des crédits, coût du risque, dividende, BPA, date du cours et liquidité."},{"ton":"cle","titre":"Télécoms : Sonatel face à Orange CI (exercice 2025, cours au 23/11/2026)","texte":"Sonatel est plus grande (1 923,1 milliards de chiffre d’affaires contre 1 197,1), plus rentable (marge nette consolidée 21,5 % contre 14,0 %), moins chère (PER 9,43 contre 17,06) et bien plus liquide.\nOrange CI croît plus vite (+18,7 % de résultat sur neuf mois 2026) et le marché lui accorde un PER plus élevé. Les deux opérateurs investissent environ 16 % de leur chiffre d’affaires dans leurs réseaux."},{"ton":"alerte","titre":"À lire avec ces conclusions","texte":"Ces comparaisons sont informatives et ne constituent pas une recommandation d’achat ou de vente."}]},{"type":"definition","titre":"Modèle de conclusion pour une fiche","contenu":"Une conclusion honnête nomme les profils, dit ce que les ratios ne disent pas, cite ses sources et sa date. Le modèle ci-dessous se complète entre crochets.","encadres":[{"ton":"info","titre":"Modèle à compléter","texte":"« Sur la base des informations disponibles pour l’exercice [année] et des cours de référence du [date], [Société A] et [Société B] présentent des profils différents. [A] affiche [atout principal : taille, rentabilité, rendement], tandis que [B] se distingue par [atout principal]. Les PER ne constituent qu’un élément de comparaison. L’analyse doit être complétée par des données homogènes sur [indicateurs sectoriels pertinents], les fonds propres, le dividende, la liquidité boursière et les perspectives. Les données proviennent de la BRVM et des comptes publiés par les sociétés, recalculées par WESTBOURSE, et de [autres sources], chacune avec sa date. Cette comparaison est informative et ne constitue pas une recommandation d’achat ou de vente. »"}]},{"type":"lexique","titre":"Sources consultées","contenu":"Chaque chiffre de ce module renvoie à l’une de ces sources. Les données de la BRVM et des sociétés font foi ; les autres sont citées avec leur date de consultation.","tableau":{"colonnes":["Source","Type de données","Date d’accès"],"lignes":[["BRVM (brvm.org)","Rapports d’activité et états financiers d’ECOC, SGBC, SNTS et ORAC, avis, cours officiels, Bulletin officiel de la cote, calendrier de paiement des dividendes","23/11/2026"],["WESTBOURSE (westbourse.com)","Comptes publiés en base, ratios recalculés (BPA, PER, ROE, marge nette, rendement), clôtures, carnet d’ordres et notes de liquidité","Lus le 24/11/2026"],["Sika Finance (sikafinance.com)","Comptes intermédiaires de 2026 non encore en base, coût du risque, solvabilité, rendements affichés, actualités","23/11/2026"],["StockAnalysis / S&P Global Market Intelligence","États financiers standardisés, PER sur douze mois glissants, résultat part du groupe, EBITDA, free cash flow, dette nette, capex, bêta","23/11/2026"],["Sonatel (sonatel.sn)","Présentation du groupe, présence dans cinq pays","23/11/2026"],["BCEAO (bceao.int)","Rapports annuels 2022 et 2023 : ratio de solvabilité minimum de l’UMOA","24/11/2026"],["allAfrica, Daba Finance","Résultats trimestriels d’ECOC, contexte sectoriel","23/11/2026"],["FGI Bourse (fgi-bourse.com)","Analyse des états financiers d’ECOC 2025","23/11/2026"],["APBEF-CI","Parts de marché bancaires en Côte d’Ivoire (avril 2026)","Via Sika Finance"]]},"encadres":[{"ton":"alerte","titre":"Avertissement","texte":"Ce module est un support pédagogique destiné aux investisseurs de la BRVM. Il ne constitue pas un conseil personnalisé d’achat ou de vente de titres. Les cours peuvent varier ; les ratios sont indicatifs et reposent sur les données disponibles à la date indiquée. Avant toute décision d’investissement, consultez un conseiller financier agréé et référez-vous aux documents officiels publiés par les sociétés et par la BRVM."}]}],"quiz":[{"question":"Les bénéfices d’une société progressent depuis trois ans, mais ses flux de trésorerie d’exploitation baissent. Que vérifier en premier ?","options":["Le nombre de ses salariés et de ses implantations","L’évolution de ses créances clients et de ses stocks","Le cours de bourse de ses principaux concurrents cotés","La date de sa prochaine assemblée générale"],"correct":1,"explication":"Un bénéfice qui ne se transforme pas en trésorerie s’explique souvent par des créances ou des stocks qui gonflent."},{"question":"Une société verse chaque année un dividende supérieur à son bénéfice. Que faut-il en conclure ?","options":["Que la distribution n’est pas soutenable durablement","Que son PER est forcément bas et son action sous-évaluée","Que l’action est garantie","Que son ROE est nul"],"correct":0,"explication":"Distribuer plus que ce que l’on gagne puise dans les réserves ou la trésorerie : cela ne peut pas durer."},{"question":"Pourquoi homogénéiser les périodes avant de calculer un PER ?","options":["Parce que le PER ne se calcule qu’en décembre","Pour associer un cours et un bénéfice de la même période","Pour éviter de payer des frais de courtage","Parce que la BRVM impose de publier tous les ratios à la même date chaque année"],"correct":1,"explication":"Un cours d’aujourd’hui rapporté à un bénéfice d’il y a deux ans donne un PER qui ne mesure rien de précis."},{"question":"Dans un tableau de suivi, que doit indiquer chaque ligne en plus des chiffres ?","options":["Une recommandation","Le nom de l’analyste","Sa source et sa date","Un objectif de cours"],"correct":2,"explication":"Une source et une date par ligne permettent de vérifier et de mettre à jour le tableau."},{"question":"Une conclusion d’analyse bien construite…","options":["désigne toujours la meilleure action","décrit des profils, écrit ses hypothèses et cite ses sources","ne mentionne jamais de chiffres","reprend la conclusion du dernier article publié sur la société par la presse"],"correct":1,"explication":"Elle décrit, ne prescrit pas : forces, faiblesses, hypothèses et sources datées."}],"qcm":{"question":"Les bénéfices d’une société progressent depuis trois ans, mais ses flux de trésorerie d’exploitation baissent. Que vérifier en premier ?","options":["Le nombre de ses salariés et de ses implantations","L’évolution de ses créances clients et de ses stocks","Le cours de bourse de ses principaux concurrents cotés","La date de sa prochaine assemblée générale"],"correct":1,"explication":"Un bénéfice qui ne se transforme pas en trésorerie s’explique souvent par des créances ou des stocks qui gonflent."},"liens":[{"label":"Le screener","href":"/screener"},{"label":"Comparer des actions","href":"/actions/compare"},{"label":"Les fiches sociétés","href":"/societes"}],"avertissement":"Ceci n’est pas un conseil en investissement. Les ratios décrivent le passé et ne garantissent aucune performance future. Investir en actions comporte un risque de perte en capital."}]$wb$::jsonb;
  v_n int;
  v_intro text;
  v_intro_ancien constant text := $wb$Niveau 2 — Analyse fondamentale. Dix leçons pour$wb$;
  v_intro_nouveau constant text := $wb$Niveau 2 — Analyse fondamentale. Un module 0 ouvre le niveau : le cours complet d’analyse fondamentale appliquée à la BRVM, en huit leçons, sur quatre sociétés cotées (Ecobank Côte d’Ivoire, Société Générale Côte d’Ivoire, Sonatel, Orange Côte d’Ivoire). Suivent dix leçons pour$wb$;
begin
  select id, content->'lessons', content->>'intro' into v_id, v_lecons, v_intro
    from public.academy_courses
   where slug = 'academy-niveau-2-fondamental'
   for update;
  if v_id is null then
    raise exception '0258 : cours academy-niveau-2-fondamental introuvable';
  end if;
  if v_lecons->0->>'titre' like 'Leçon 0.%' then
    raise notice '0258 : module 0 déjà présent, rien à faire';
    return;
  end if;
  if jsonb_array_length(v_lecons) <> 10 or v_lecons->0->>'titre' not like 'Leçon 1 — %' then
    raise exception '0258 : état inattendu (% leçons, première : %)',
      jsonb_array_length(v_lecons), v_lecons->0->>'titre';
  end if;

  v_n := jsonb_array_length(v_module0);
  if v_n <> 8 then
    raise exception '0258 : 8 leçons attendues dans le module 0, % reçues', v_n;
  end if;

  update public.academy_courses
     set content = jsonb_set(content, '{lessons}', v_module0 || v_lecons),
         updated_at = now()
   where id = v_id;

  update public.academy_progress set lesson_idx = lesson_idx + 1000
   where course_id = v_id;
  update public.academy_progress set lesson_idx = lesson_idx - 1000 + v_n
   where course_id = v_id and lesson_idx >= 1000;

  update public.academy_notes set lesson_idx = lesson_idx + 1000
   where course_id = v_id;
  update public.academy_notes set lesson_idx = lesson_idx - 1000 + v_n
   where course_id = v_id and lesson_idx >= 1000;

  -- Introduction du cours : « Dix leçons pour… » devient faux. Remplacement
  -- ciblé sur le texte exact ; s’il a changé en base, il est laissé tel quel.
  if strpos(v_intro, v_intro_ancien) = 1 then
    update public.academy_courses
       set content = jsonb_set(content, '{intro}', to_jsonb(replace(v_intro, v_intro_ancien, v_intro_nouveau)))
     where id = v_id;
  else
    raise notice '0258 : introduction différente en base, laissée telle quelle';
  end if;

  raise notice '0258 : module 0 inséré (% leçons), progression et notes décalées de %', v_n, v_n;
end
$do$;

commit;

-- Vérification après application : 18 leçons, « Leçon 0.1 » à « Leçon 0.8 »
-- puis « Leçon 1 » à « Leçon 10 », progression aux index 8 et au-delà.
